// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Düzenli ifadeler (regex), sonlu durum makineleri, özyineleme (recursion) izleme, yığınla ifade değerlendirme ve derleyici aşamaları (orta).
const ozComputing16Orta = <(String, String, List<String>, String)>[
  ('Bir e-ticaret sitesinde yalnızca \'kargo\' veya \'teslimat\' kelimelerini tam olarak içeren tek kelimelik etiketleri seçen desen hangisidir?', '^(kargo|teslimat)\$', ['^[kargo|teslimat]\$', '^kargo|teslimat\$', '(kargo)+(teslimat)+'], 'Gruplama parantezi olmadan \'^kargo|teslimat\$\' yazılırsa \'^\' yalnız sol seçeneğe bağlanır; parantez çıpaları her iki seçeneğe uygular.'),
  ('Geliştiricinin \'192.168.1.1\' adresini doğrulamak için yanlışlıkla \'^192.168.1.1\$\' yazması hangi beklenmedik girdinin kabul edilmesine yol açar?', '192X168Y1Z1', ['192.168.1.10', '10.192.168.1.1', '192..168.1.1'], 'Kaçışsız nokta (.) herhangi bir tek karakterle eşleşir; gerçek nokta aramak için \'\\.\' kullanılmalıdır.'),
  ('HTML metni olan \'<b>Kalın</b> ve <b>Önemli</b>\' üzerinde \'<.*>\' deseni çalıştırıldığında neden iki ayrı etiket yerine tüm metin tek parça halinde eşleşir?', 'Yıldız niceleyicisi varsayılan olarak açgözlü (greedy) davrandığı için en son \'>\' işaretine kadar ilerler', ['Nokta karakteri HTML açısal parantezlerini otomatik olarak yok saydığı için tüm satırı birleştirir', 'Küçüktür ve büyüktür sembolleri düzenli ifadelerde gruplama operatörü olarak değerlendirilir', 'Boşluk karakterleri iki etiket arasındaki sınırı ortadan kaldırarak tek bir kelime oluşturur'], 'Açgözlü (greedy) niceleyiciler mümkün olan en uzun alt dizgeyi tüketir; ilk \'<\' ile en son \'>\' arasını tek eşleşme yapar.'),
  ('Metin temizleme aracında yan yana tekrar eden aynı kelimeleri (örneğin \'çok çok güzel\' içindeki \'çok çok\') yakalamak için kullanılan \'\\b(\\w+)\\s+\\1\\b\' ifadesindeki \'\\1\' neyi ifade eder?', 'Birinci yakalama grubunun eşleştiği tam metnin geri referansını', ['Kelimenin sonuna rakam olarak 1 sayısının eklenmesini', 'Eşleşmenin yalnızca satırın birinci indeksinden başlamasını', 'Gruptaki desenin yalnız bir karakter uzunluğunda olmasını'], '\\1 geri referansı (backreference), ilk parantez grubunun o an yakaladığı dizgenin birebir aynısını tekrar arar.'),
  ('Önemli: \'([ab])\\1\' düzenli ifadesi ile \'[ab]{2}\' düzenli ifadesi karşılaştırıldığında hangi dizge ikincisiyle eşleştiği halde birincisiyle eşleşmez?', 'ab', ['aa', 'bb', 'aba'], '\'([ab])\\1\' ilk seçilen harfin aynısını beklediği için yalnızca \'aa\' ve \'bb\' üretir; \'[ab]{2}\' ise \'ab\' ve \'ba\' dizgelerini de kabul eder.'),
  ('Bir URL ayrıştırıcıda \'https?://(?:www\\.)?ornek\\.com\' ifadesindeki \'(?:www\\.)\' yapısında yer alan \'?:\' dizisinin amacı nedir?', 'Grubu niceleyici uygulamak için birleştirirken bellekte numaralı yakalama grubu oluşturmamak', ['Alt alan adının yalnızca güvenli bağlantı protokolü kullanıldığında aranmasını sağlamak', 'Nokta karakterinden önce gelen harflerin büyük-küçük harf duyarsız olmasını belirtmek', 'İfadenin geri kalan kısmını yorum satırı haline getirerek motorun okumamasını sağlamak'], '(?:...) yakalamayan grup (non-capturing group) oluşturur; gruplama yapar ancak \\1, \\2 numaralandırmasını işgal etmez.'),
  ('Aşağıdaki dizgelerden hangisi \'^[A-Z][a-z]{2,4}\\d?\$\' düzenli ifadesiyle tam eşleşme sağlar?', 'Mart9', ['nisan5', 'A1', 'Haziran2'], 'Büyük harfle başlamalı, ardından 2 ila 4 küçük harf gelmeli ve isteğe bağlı tek rakamla bitmelidir: \'M\' + \'art\' (3 küçük harf) + \'9\' koşulu sağlar.'),
  ('Dosya listesinde \'.txt\' veya \'.csv\' uzantılı olup dosya adı en az bir harf ya da rakam içeren kayıtları filtreleyen desen hangisidir?', '^[A-Za-z0-9]+\\.(txt|csv)\$', ['^[A-Za-z0-9]*.(txt|csv)\$', '^\\w+\\.[txt|csv]\$', '[A-Za-z0-9]+\\.(txt&csv)'], '+ en az bir karakteri garanti eder, \\. gerçek noktayı eşler ve (txt|csv) iki uzantı arasında seçim yapar.'),
  ('Bir geliştirici IPv4 adreslerini doğrulamak için \'^(\\d{1,3}\\.){3}\\d{1,3}\$\' desenini kullandığında hangi geçersiz IP adresi bu kontrolden yanlışlıkla geçer?', '999.300.256.888', ['192.168.1', '10.0.0.1.5', '255.255.255.a'], '\\d{1,3} yalnızca basamak sayısını (1-3 rakam) kontrol eder; 0-255 sayısal değer sınırını denetlemediğinden 999 gibi değerleri kabul eder.'),
  ('İkili alfabede tanımlanan \'^1(01)*0\$\' düzenli ifadesinin kabul ettiği en kısa dizge hangisidir?', '10', ['1010', '0', '101'], '(01)* grubu sıfır kez tekrarlanabildiğinden baştaki \'1\' ve sondaki \'0\' birleşerek en kısa kabul dizgesi olan \'10\'u üretir.'),
  ('Bir veri tabanı sorgusunda \'^[aeiouAEIOU].*[aeiouAEIOU]\$\' düzenli ifadesi hangi kelimeleri seçer?', 'En az iki karakterli olup hem ünlü harfle başlayan hem ünlü harfle biten dizgeleri', ['Yalnızca ünlü harflerden oluşan ve hiç ünsüz barındırmayan kelimeleri', 'Tek bir ünlü harften ibaret olan \'a\' veya \'e\' gibi bağlaçları', 'İçinde en az iki tane yan yana ünlü harf bulunduran tüm sözcükleri'], 'Başta bir ünlü ve sonda ayrı bir ünlü karakter tüketildiği için dizge en az 2 uzunluğunda olmalı; ortadaki \'.*\' her şeye izin verir.'),
  ('Bir günlük analizinde \'\\[HATA\\]\' deseni neden köşeli parantezlerin önünde ters eğik çizgi içerir?', 'Köşeli parantezler kaçırılmazsa \'H\', \'A\' veya \'T\' harflerinden yalnız birini seçen karakter sınıfına dönüşür', ['Ters eğik çizgi olmadan büyük harfler otomatik olarak küçük harfe çevrilir', 'Köşeli parantezler düzenli ifadelerde satır sonu çıpası olarak görev yapar', 'Kaçış karakteri eklenmezse desen yalnızca sayısal hata kodlarını arar'], 'Kaçışsız \'[HATA]\' ifadesi H, A veya T karakterlerinden tek bir tanesiyle eşleşir; gerçek \'[HATA]\' metni için parantezler kaçırılmalıdır.'),
  ('Çok satırlı (multiline, \'m\' bayrağı) mod etkinleştirildiğinde \'^\' ve \'\$\' çıpalarının davranışında ne değişir?', 'Yalnızca tüm metnin başı ve sonu yerine her bir satır sonu karakterinin öncesi ve sonrasıyla da eşleşirler', ['Nokta meta karakterinin satır sonu karakterlerini de kapsaması otomatik olarak sağlanır', 'Boşluk karakterlerinin tamamı eşleşme sırasında görmezden gelinmeye başlanır', 'Yakalama gruplarının numaralandırması her yeni satırda sıfırlanarak baştan başlar'], '\'m\' bayrağı ^ ve \$ çıpalarını metin sınırı yerine satır sınırı duyarlı hale getirir; noktanın \'\\n\' eşlemesi ise \'s\' (dotall) bayrağıdır.'),
  ('Düzenli ifade motorlarında \'s\' (dotall / single-line) bayrağının açılması hangi meta karakterin kapsamını genişletir?', 'Nokta (.) karakterinin yeni satır (\'\\n\') karakteriyle de eşleşmesini sağlar', ['\'\\s\' kısayolunun yalnızca normal boşluk tuşunu tanımasını zorunlu kılar', 'Yıldız (*) niceleyicisini varsayılan olarak tembel moda geçirir', 'Dolar (\$) çıpasının satır sonundaki boşlukları silmesini sağlar'], 'Normalde nokta (.) satır sonu hariç her karakteri eşler; dotall (\'s\') bayrağı ile çok satırlı bloklar \'.\' ile geçilebilir.'),
  ('Aşağıdaki dizgelerden hangisi \'^(ab|ba)+\$\' düzenli ifadesiyle eşleşmez?', 'aabb', ['abba', 'abab', 'baab'], 'Desen dizgeyi ikişerli bloklara böldüğünde her bloğun \'ab\' veya \'ba\' olmasını şart koşar; \'aabb\' dizgesinin ilk ikilisi \'aa\' olduğu için reddedilir.'),
  ('Bir metindeki tüm rakam dizilerini bulup her birini parantez içine almak isteyen bir geliştirici, arama deseni \'(\\d+)\' iken değiştirme (replace) şablonuna ne yazmalıdır?', '(\$1)', ['(\\d+)', '(?1)', '[\\0+]'], 'Değiştirme şablonlarında \$1 (veya bazı araçlarda \\1), birinci yakalama grubunun eşleştiği metni temsil eder.'),
  ('Neden \'^[A-Z]+\\d+\$\' deseni \'en az bir büyük harf ve bir rakam içeren parolalar\' kuralını doğrulamak için hatalı bir seçimdir?', 'Harflerin tamamının rakamlardan önce gelmesini zorunlu kılar ve \'9A\' veya \'A1B\' gibi girdileri reddeder', ['Rakam sayısının büyük harf sayısına tam olarak eşit olmasını şart koşar', 'Boş dizgeyi de geçerli parola olarak kabul ederek güvenlik açığı doğurur', 'Küçük harfleri ve özel sembolleri büyük harf sınıfının parçası sayar'], 'Ardışık yazılan \'[A-Z]+\\d+\' sıra bağımlılığı yaratır; karışık sıralı karakter koşulları için lookahead veya çoklu kontrol gerekir.'),
  ('C veya Java kaynak kodundaki \'/* ... */\' çok satırlı yorum bloklarını yakalarken birden fazla yorum bloğunun tek seferde birleşmemesi için (\'s\' dotall modunda) hangi desen uygundur?', '/\\*.*?\\*/', ['/\\*.*\\*/', '/*.*?*/', '/\\*[^/]*\\*/'], 'Yıldız karakteri meta karakter olduğundan \'\\*\' ile kaçırılır, \'.*?\' tembel niceleyicisi ise ilk kapanış \'*/\' dizisinde durmayı sağlar.'),
  ('Bir telefon numarası alanında hem \'05321234567\' hem de \'532 123 45 67\' biçimlerini kabul eden aşağıdaki ifadelerden hangisi doğrudur?', '^0?5\\d{2}\\s?\\d{3}\\s?\\d{2}\\s?\\d{2}\$', ['^0+5\\d{2}\\s+\\d{3}\\s+\\d{2}\\s+\\d{2}\$', '^[05]\\d{9}\$', '^0?5\\d{2}(\\s\\d{2}){4}\$'], 'Baştaki \'0?\' sıfırı, aralardaki \'\\s?\' ise boşlukları isteğe bağlı kılarak her iki yazım biçimini de doğrular.'),
  ('Bir metin dosyasındaki tamamen boş olan (yalnızca boşluk veya sekme içerebilen ya da hiç karakter içermeyen) satırları çok satırlı modda yakalayan desen hangisidir?', '^[ \\t]*\$', ['^\\s+\$', '^.\$', '^[^a-zA-Z]+\$'], '\'^[ \\t]*\$\' hem sıfır karakterli boş satırları hem de yalnızca boşluk/sekme içeren satırları satır birleştirmeden seçer.'),
  ('Türkçe metin işleyen bir uygulamada yalnızca \'[a-zA-Z]+\' deseni kullanıldığında \'öğrenci\' kelimesinde nasıl bir sorun yaşanır?', 'ASCII dışındaki \'ö\' ve \'ğ\' harflerinde eşleşme bölünerek yalnızca \'renci\' kısmı yakalanır', ['Kelimenin tamamı büyük harfe çevrilerek \'ÖĞRENCİ\' olarak döndürülür', 'Düzenli ifade motoru Türkçe karakter görünce çalışma zamanı istisnası fırlatır', 'Yalnızca ilk iki harf olan \'öğ\' seçilip geri kalan ASCII harfleri atlanır'], '[a-zA-Z] yalnızca 26 harflik İngilizce ASCII aralığını kapsar; ç, ğ, ı, İ, ö, ş, ü harfleri açıkça sınıfa eklenmeli veya Unicode özelliği (\\p{L}) kullanılmalıdır.'),
  ('Unicode destekli düzenli ifade motorlarında hangi yazılımdan bağımsız tüm dillerdeki (Türkçe, Kiril, Yunanca vb.) harf karakterlerini yakalayan özellik sınıfı hangisidir?', '\\p{L}', ['\\u{A-Z}', '\\w*', '[a-z+]'], 'Unicode kategori sözdiziminde \\p{L} (Letter) hangi alfabeden olursa olsun tüm harf karakterleriyle eşleşir.'),
  ('Bir kullanıcı girdisinde ters eğik çizgi karakterinin kendisini (\'\\\') aramak için JSON veya çift tırnaklı kaynak kod dizgesi içinde çoğu zaman dört adet \'\\\\\\\\\' yazılmasının nedeni nedir?', 'Önce programlama dilinin dizge kaçışı iki çizgiyi bire indirir, ardından regex motoru kaçış için iki çizgi bekler', ['Ters eğik çizgi karakteri UTF-8 kodlamasında 4 bayt yer kapladığı için dört kez yazılır', 'İlk iki çizgi satır başını, son iki çizgi ise satır sonunu temsil etmek için kullanılır', 'Dört çizgiden az yazıldığında ifade otomatik olarak yorum satırı kabul edilir'], 'Kaynak kod dizgesi \'\\\\\\\\\' ifadesini \'\\\\\' metnine çevirir; regex motoru da \'\\\\\' desenini tek bir edebi \'\\\' karakteri olarak yorumlar.'),
  ('Aşağıdaki düzenli ifadelerden hangisi uzunluğu 3\'ün tam katı olan (0, 3, 6, 9... karakterli) ikili dizgeleri kabul eder?', '^([01]{3})*\$', ['^[01]{3}*\$', '^[01]*3\$', '^([01]*){3}\$'], 'Üçlü ikili blok \'[01]{3}\' grup içine alınıp \'*\' ile sıfır veya daha fazla kez tekrarlandığında uzunluk 3k (k >= 0) olur.'),
  ('Neden \'[^11]\' ifadesi \'ardışık iki 1 dışındaki dizgeler\' anlamına gelmez?', 'Köşeli parantez tek bir karakter kümesidir; tekrar eden \'1\' etkisiz kalır ve ifade yalnızca \'1 olmayan tek karakter\' demektir', ['Köşeli parantez içindeki sayılar her zaman onluk tabanda 11 sayısı olarak okunur', 'Şapka işareti rakamlardan önce yazıldığında yalnızca negatif sayıları filtreler', 'İki aynı rakamın sınıf içinde bulunması ifadeyi boş küme haline getirir'], 'Karakter sınıfları dizi değil küme mantığıyla çalışır ve her zaman tek karakter tüketir; \'[^11]\' ifadesi \'[^1]\' ile tamamen aynıdır.'),
  ('Düzenli ifade operatörlerinin bağlanma önceliği (en yüksekten en düşüğe doğru) hangi seçenekte doğru sıralanmıştır?', 'Gruplama parantezi, tekrar niceleyicileri (* + ?), ardışık birleştirme, seçim (|)', ['Seçim (|), ardışık birleştirme, tekrar niceleyicileri (* + ?), gruplama parantezi', 'Ardışık birleştirme, gruplama parantezi, seçim (|), tekrar niceleyicileri (* + ?)', 'Tekrar niceleyicileri (* + ?), seçim (|), gruplama parantezi, ardışık birleştirme'], 'En yüksek öncelik parantezdedir; ardından *, +, ? niceleyicileri, sonra yan yana yazma (concatenation) ve en düşük öncelikle \'|\' seçimi gelir.'),
  ('Operatör önceliği dikkate alındığında \'kedi|köpek+\' düzenli ifadesi aşağıdakilerden hangisiyle eşleşir?', 'kedi veya sonunda en az bir \'k\' bulunan köpekkkk... dizgesi', ['kedi ve köpek kelimelerinin art arda sıralandığı \'kediköpek\' dizgesi', '\'köpek\' kelimesinin bütünüyle tekrarlandığı \'köpekköpek\' dizgesi', '\'kedi\' kelimesinin son harfinin de tekrarlandığı \'kediiii\' dizgesi'], '\'+\' niceleyicisi yalnızca \'k\' harfine, \'|\' ise en dışta \'kedi\' ile \'köpek+\' seçenekleri arasına uygulanır.'),
  ('Bir dosya yolunda Windows sürücü harfini ve iki nokta üst üsteyi (örneğin \'C:\\\' veya \'D:\\\') satır başında doğrulamak için hangi desen yazılmalıdır?', '^[A-Za-z]:\\\\', ['^[A-Za-z]:\\', '^[A-Z]:/\$', '^\\w:\\\\+\$'], 'Sürücü tek bir harftir \'[A-Za-z]\', ardından \':\' gelir ve ters eğik çizgi regex içinde \'\\\\\' ile kaçırılır.'),
  ('Saat bilgisini 24 saatlik biçimde (\'00:00\' ile \'23:59\' arası) hatasız doğrulayan düzenli ifade hangisidir?', '^([01]\\d|2[0-3]):[0-5]\\d\$', ['^[0-2]\\d:[0-5]\\d\$', '^([0-9]|2[0-4]):[0-6]\\d\$', '^\\d{2}:\\d{2}\$'], '\'[0-2]\\d\' ifadesi \'29:00\' gibi geçersiz saatlere izin verir; saat kısmı 00-19 (\'[01]\\d\') veya 20-23 (\'2[0-3]\'), dakika ise 00-59 (\'[0-5]\\d\') olmalıdır.'),
  ('Bir dizgede en az iki adet \'a\' harfi bulunduğunu (arada veya uçlarda başka karakterler olabilir) denetleyen en yalın düzenli ifade hangisidir?', 'a.*a', ['a{2,}', '^a+a+\$', '[^a]*a[^a]*'], '\'a{2,}\' yalnızca yan yana duran \'aa\' dizisini yakalar; \'a.*a\' ise aralarında sıfır veya daha fazla herhangi karakter bulunan en az iki \'a\' varlığını doğrular.'),
  ('İçinde tam olarak iki adet \'1\' bulunan tüm ikili dizgeleri tanımlayan düzenli ifade hangisidir?', '^0*10*10*\$', ['^[01]*1[01]*1[01]*\$', '^0+10+10+\$', '^(0*1){2}\$'], '\'[01]*\' kullanılırsa fazladan \'1\' rakamları girebilir; \'(0*1){2}\' ise sondaki sıfırları kaçırır. \'^0*10*10*\$\' tam iki \'1\' ve istenildiği kadar \'0\' sağlar.'),
  ('Bir geliştirici yalnızca ünsüz harflerden oluşan 3 harfli küçük kelimeleri bulmak için \'^[^aeiou]{3}\$\' yazdığında hangi girdinin kabul edilmesi bu desenin hatalı olduğunu gösterir?', '12!', ['tren', 'aba', 'aei'], '\'[^aeiou]\' ünsüz harfler demek değildir; rakamlar, boşluklar ve semboller dahil küçük ünlüler dışındaki her karakteri kabul eder.'),
  ('Kullanıcı girdisindeki baştaki ve sondaki tüm boşlukları (trim işlemi) tek bir regex ikamesiyle silmek için hangi desen boş dizgeyle (\'\') değiştirilmelidir?', '^\\s+|\\s+\$', ['^\\s+.*\\s+\$', '\\s+', '^\\s*\$'], '\'^\\s+\' baştaki boşlukları, \'\\s+\$\' sondaki boşlukları seçer; aradaki boşluklara dokunmadan ikisini de siler.'),
  ('Düzenli ifadelerde \'(?P<yil>\\d{4})\' veya \'(?<yil>\\d{4})\' sözdizimi hangi özelliği sağlar?', 'Yakalama grubuna sıra numarası yanında anlamlı bir isimle erişebilmeyi', ['Yalnızca \'yil\' kelimesinden sonra gelen 4 rakamın seçilmesini', 'Eşleşen metnin otomatik olarak tam sayı veri tipine dönüştürülmesini', 'Grubun içindeki niceleyicinin geri izleme yapmasını engellemeyi'], 'İsimlendirilmiş yakalama grupları (named capturing groups), karmaşık desenlerde grup numarası saymak yerine isimle (\'yil\') veri çekmeyi sağlar.'),
  ('Bir derleyicinin sözcüksel analizcisinde C tarzı değişken adlarını (harf veya alt çizgi ile başlayan, ardından harf, rakam veya alt çizgi gelebilen dizgeler) tanımlayan ifade hangisidir?', '^[A-Za-z_][A-Za-z0-9_]*\$', ['^[A-Za-z0-9_]+\$', '^[A-Za-z][A-Za-z0-9_]+\$', '^_?[A-Za-z]+\\d*\$'], 'Değişken adları rakamla başlayamaz ama tek harf/alt çizgi olabilir; bu yüzden ilk karakter \'[A-Za-z_]\', devamı ise \'*\' ile \'[A-Za-z0-9_]*\' olur.'),
  ('Kuramsal bilgisayar biliminde Kleene teoremine göre düzenli ifadelerin tanımlama gücü hangi soyut hesaplama modeliyle tam olarak eşdeğerdir?', 'Sonlu durum otomatları (DFA ve NFA)', ['Yığınlı otomatlar (Pushdown Automata)', 'Turing makineleri', 'Doğrusal sınırlı otomatlar'], 'Kleene teoremi (geri referans ve lookaround gibi modern uzantılar hariç) düzenli ifadelerin tam olarak sonlu otomatların tanıdığı düzenli dilleri ürettiğini kanıtlar.'),
  ('Deterministik olmayan bir sonlu otomatta (NFA) bir girdi dizgesinin \'kabul edildiği\' ne zaman söylenir?', 'Olası paralel hesaplama yollarından en az biri dizge bittiğinde kabul durumuna ulaşıyorsa', ['Olası tüm hesaplama dallarının istisnasız hepsi aynı anda kabul durumunda sonlanıyorsa', 'Dizgenin ilk karakteri okunduğu anda makine doğrudan başlangıç durumuna geri dönüyorsa', 'Hiçbir epsilon geçişi kullanılmadan en kısa yoldan tuzak durumuna varılabiliyorsa'], 'NFA kabul ölçütü varoluşsaldır: tek bir geçerli yolun bile dizge sonunda F kümesindeki bir durumda bitmesi kabul için yeterlidir.'),
  ('Hem \'0\' sayısının çift hem de \'1\' sayısının tek olduğu ikili dizgeleri tanıyan en küçük deterministik sonlu otomat kaç durumdan oluşur?', '4 durum', ['2 durum', '6 durum', '8 durum'], '0\'ların paritesi (çift/tek: 2 seçenek) ile 1\'lerin paritesi (çift/tek: 2 seçenek) bağımsız olduğundan çarpım otomatiği 2 x 2 = 4 durum gerektirir.'),
  ('En anlamlı bitten (MSB - soldan sağa) okunan ikili tam sayıların 3\'e kalansız bölünüp bölünmediğini denetleyen DFA\'da durumlar neyi temsil eder?', 'O ana kadar okunan ikili sayının 3 ile bölümünden kalanları', ['Dizgenin son üç bitinin onluk tabandaki basamak toplamlarını', 'Okunan toplam \'1\' bitlerinin sayısının 2 ile bölümünden kalanını', 'Girdi dizgesinin kalan okunmamış bit sayısının üçte birini'], 'Soldan yeni bir b biti eklendiğinde yeni değer \'2 * eski_değer + b\' olur; mod 3 aritmetiğinde yalnızca 0, 1 ve 2 kalanlarını izleyen 3 durum yeterlidir.'),
  ('Soldan sağa okunan ikili sayıların 3\'e tam bölünmesini denetleyen DFA\'da (durumlar kalan 0, kalan 1, kalan 2), makine \'kalan 1\' durumundayken \'1\' biti gelirse hangi duruma geçer?', 'Kalan 0 durumuna', ['Kalan 1 durumuna', 'Kalan 2 durumuna', 'Reddedici tuzak durumuna'], 'Mevcut kalan 1 iken sağına \'1\' biti eklemek sayıyı (2 * 1 + 1) = 3 yapar; 3 mod 3 = 0 olduğundan \'Kalan 0\' durumuna geçilir.'),
  ('NFA\'dan eşdeğer bir DFA elde etmek için kullanılan Altküme Kurulumu (Subset Construction) algoritmasında n durumlu bir NFA en kötü durumda kaç durumlu bir DFA üretebilir?', '2^n durumlu', ['n^2 durumlu', '2n durumlu', 'n! durumlu'], 'DFA\'nın her bir durumu NFA durumlarının bir alt kümesine karşılık geldiğinden n elemanlı kümenin kuvvet kümesi büyüklüğü olan 2^n üst sınırdır.'),
  ('Bir NFA\'da q durumunun \'ε-kapanışı\' (epsilon-closure) ne demektir?', 'q durumunun kendisi dahil yalnızca sıfır veya daha fazla ε-geçişi izlenerek ulaşılabilen tüm durumlar kümesi', ['q durumundan çıkıp kabul durumuna hiçbir zaman ulaşamayan ölü durumların listesi', 'Girdi alfabesindeki tüm harfler birer kez okunduğunda q\'dan varılan komşu durumlar', 'q durumuna dışarıdan gelen tüm okların silinmesiyle elde edilen yalıtılmış alt otomat'], 'ε-kapanışı(q), q\'yu içerir ve q\'dan sadece ε etiketli kenarlarla erişilebilen her durumu özyinelemeli olarak kümeye katar.'),
  ('NFA\'ların deterministik olmaması onlara DFA\'lara kıyasla dil tanıma gücü açısından nasıl bir üstünlük kazandırır?', 'Dil tanıma gücü açısından hiçbir fark yoktur; her ikisi de tam olarak düzenli dilleri tanır', ['NFA\'lar bağlamdan bağımsız dillerin yarısını tanıyabilirken DFA\'lar tanıyamaz', 'NFA\'lar sonsuz uzunluktaki rastgele dizgeleri sınıflandırabilirken DFA\'lar sonlu kalır', 'NFA\'lar iç içe parantez sayma işlemlerini ek bellek olmadan yapabilir'], 'Rabin-Scott teoremine göre her NFA altküme kurulumuyla eşdeğer bir DFA\'ya dönüştürülebilir; fark yalnızca gösterim kısalığıdır, tanınan dil sınıfı aynıdır.'),
  ('Tam tanımlı bir DFA\'nın tanıdığı L dilinin tümleyenini (Σ* - L) tanıyan yeni bir DFA elde etmek için ne yapılması yeterlidir?', 'Kabul durumlarını kabul etmeyen duruma, kabul etmeyen durumları ise kabul durumuna çevirmek', ['Diyagramdaki tüm geçiş oklarının yönünü tersine çevirip başlangıç ile sonu değiştirmek', 'Başlangıç durumundan diğer tüm durumlara birer epsilon geçişi eklemek', 'Tuzak durumlarını silerek makineyi kısmi geçiş fonksiyonlu hale getirmek'], 'DFA tam ve deterministik olduğundan her dizge tam bir durumda biter; F kümesini Q - F yapmak reddedilen her dizgeyi kabul, kabul edileni ret yapar.'),
  ('{a, b} alfabesinde \'aa\' alt dizgesini kesinlikle içermeyen dizgeleri tanıyan tam tanımlı en küçük DFA\'da tuzak durumu dahil kaç durum bulunur?', '3 durum', ['2 durum', '4 durum', '5 durum'], 'q0 (son harf \'a\' değil, kabul), q1 (son harf tek \'a\', kabul) ve q2 (\'aa\' görüldü, reddedici tuzak durum) olmak üzere 3 durum gerekir.'),
  ('Sayısal mantık tasarımında kullanılan Moore ve Mealy sonlu durum makineleri arasındaki temel fark nedir?', 'Moore makinesinde çıktı yalnız mevcut duruma bağlıyken Mealy makinesinde hem mevcut duruma hem o anki girdiye bağlıdır', ['Moore makinesi yalnızca ikili girdileri işlerken Mealy makinesi ondalık sayıları işler', 'Mealy makinesinde durum sayısı her zaman Moore makinesinin iki katından fazladır', 'Moore makinesi saat darbesi olmadan asenkron çalışırken Mealy yalnızca yığın kullanır'], 'Moore modelinde çıktılar durum düğümlerinin içine yazılır; Mealy modelinde ise çıktılar geçiş oklarının üzerine \'girdi / çıktı\' biçiminde yazılır.'),
  ('25 TL\'lik içecek veren bir otomat yalnızca 10 TL ve 20 TL madeni para kabul etmektedir (para üstü olsun ya da olmasın toplam >= 25 TL olduğunda içecek verir ve sıfırlanır). Biriken tutarı izlemek için başlangıç durumu dahil kaç bakiye durumu gerekir?', '3 durum (0 TL, 10 TL, 20 TL)', ['6 durum (0, 5, 10, 15, 20, 25 TL)', '2 durum (Yetersiz ve Yeterli)', '5 durum (0, 10, 20, 30, 40 TL)'], '5 TL madeni para olmadığından ulaşılabilecek ara bakiyeler yalnızca 0 TL, 10 TL ve 20 TL\'dir; 25 TL\'yi aşan her geçiş içeceği verip 0 TL durumuna döner.'),
  ('Bir trafik ışığı denetleyicisi sırasıyla \'Yeşil -> Sarı -> Kırmızı -> Kırmızı+Sarı -> Yeşil\' döngüsünde çalışmaktadır. Işıkların \'Kırmızı\' ve \'Yeşil\' öncesi \'Sarı\' geçişinde ikisini ayırt edebilmek için neden tek bir \'Sarı\' durumu yetmez?', 'Aynı zamanlayıcı darbesi geldiğinde birinden Kırmızıya diğerinden Yeşile geçileceği için önceki yön bilgisini farklı durumlar tutmalıdır', ['Sarı lambanın elektrik gerilimi kırmızı ve yeşil lambalardan farklı bir frekansta çalışır', 'Sonlu durum makinelerinde bir duruma birden fazla geçiş okunun gelmesi yasaktır', 'Dört durumdan az olan makineler donanımda ikili sayaçlarla kodlanamaz'], 'Deterministik makinede sadece \'Süre Doldu\' sinyaliyle sıradaki ışığın Kırmızı mı Yeşil mi olacağını bilmek için \'Sarı (Kırmızıya gidiyor)\' ve \'Kırmızı+Sarı (Yeşile gidiyor)\' iki ayrı durum olmalıdır.'),
  ('Aşağıdaki dillerden hangisi hiçbir sonlu durum otomatı (DFA veya NFA) tarafından TANINAMAZ?', 'Eşit sayıda \'0\' ve ardından eşit sayıda \'1\' içeren {0^n 1^n | n >= 0} dili', ['Uzunluğu 5 ile bölümünden 3 kalanını veren ikili dizgeler dili', 'Başında \'101\' ve sonunda \'010\' alt dizgesi bulunan tüm ikili dizgeler dili', 'İçinde \'0\' rakamı çift sayıda ve \'1\' rakamı çift sayıda geçen dizgeler dili'], '0^n 1^n dilini tanımak için n\'nin keyfi büyüklükteki değerini hatırlamak gerekir; sonlu durum sayısına sahip bir otomat sınırsız n değerini sayamaz.'),
  ('DFA minimizasyonu (durum sayısını en aza indirme) algoritmasında iki durumun \'ayırt edilemez\' (eşdeğer) olması ne anlama gelir?', 'Her iki durumdan da hangi girdi dizgesi okunursa okunsun ikisinin birden aynı kabul veya aynı ret sonucuna varması', ['Her iki durumun da başlangıç durumuna eşit uzaklıkta bulunması', 'Durumlardan çıkan geçiş oklarının aynı renk ve etiketle çizilmiş olması', 'İki durum arasında karşılıklı birer epsilon geçişinin tanımlanmış olması'], 'Myhill-Nerode eşdeğerliğine göre her w dizgesi için δ*(p, w) ∈ F ⇔ δ*(q, w) ∈ F koşulunu sağlayan p ve q durumları tek bir durumda birleştirilebilir.'),
  ('Bir DFA\'yı minimize etmeye başlamadan önce yapılması gereken ilk temizlik adımı hangisidir?', 'Başlangıç durumundan hiçbir girdi dizisiyle ulaşılamayan (erişilemez) durumları silmek', ['Kabul durumlarının tamamını tek bir yeni kabul durumunda birleştirmek', 'Üzerinde öz-döngü (self-loop) bulunan tüm durumları diyagramdan çıkarmak', 'Tuzak durumundan başlangıç durumuna geri dönüş oku eklemek'], 'Başlangıçtan erişilemeyen (unreachable) durumlar makinenin tanıdığı dili hiç etkilemez ancak tablo doldurma algoritmasını gereksiz büyütür; önce onlar elenir.'),
  ('Ağ protokollerinde TCP bağlantısının yaşam döngüsünü (CLOSED, LISTEN, SYN_SENT, ESTABLISHED, FIN_WAIT_1, TIME_WAIT vb.) tanımlamak için neden sonlu durum makinesi kullanılır?', 'Her ağ paketinin yalnızca o anki bağlantı durumuna göre geçerli olup olmadığını kesin ve deterministik biçimde yönetmek için', ['Gönderilen veri paketlerinin içeriğini sıkıştırarak bant genişliğinden tasarruf etmek için', 'Yönlendiriciler arasındaki en kısa fiziksel fiber optik rotayı dinamik hesaplamak için', 'Şifreleme anahtarlarını asal çarpanlarına ayırarak kimlik doğrulaması yapmak için'], 'Protokol doğrulamasında gelen bir ACK veya FIN bayrağının meşru bir geçiş mi yoksa protokol hatası/saldırısı mı olduğu mevcut TCP durumuna göre belirlenir.'),
  ('L1 dilini tanıyan m durumlu bir DFA ile L2 dilini tanıyan n durumlu bir DFA verildiğinde, her iki dilin kesişimini (L1 ∩ L2) tanıyan çarpım otomatiğinde hangi durumlar kabul durumu olarak seçilir?', 'Birinci bileşeni L1\'in kabul durumu VE ikinci bileşeni L2\'nin kabul durumu olan (p, q) durum çiftleri', ['Bileşenlerinden en az biri kabul durumu olan tüm (p, q) durum çiftleri', 'Yalnızca başlangıç durumlarının kartezyen çarpımından oluşan tekil çift', 'Birinci bileşeni kabul durumu olup ikinci bileşeni ret durumu olan çiftler'], 'Kesişim (L1 ∩ L2) her iki makinenin de aynı anda kabul vermesini gerektirdiğinden F = F1 × F2 seçilir; birleşim (L1 ∪ L2) olsaydı \'en az biri kabul\' seçilirdi.'),
  ('{a, b} alfabesinde tüm \'a\' harflerinin tüm \'b\' harflerinden önce geldiği (örneğin ε, \'aaa\', \'bb\', \'aabb\' geçerli; \'ba\', \'aba\' geçersiz) dili tanıyan tam tanımlı DFA\'da geçişler nasıl olmalıdır?', 'İlk \'b\' görüldüğünde ikinci bir kabul durumuna geçilmeli, bu durumdayken \'a\' gelirse reddedici tuzak durumuna düşülmelidir', ['Her \'a\' geldiğinde sayaç artırılmalı ve her \'b\' geldiğinde sayaç azaltılarak sıfır kontrolü yapılmalıdır', 'Başlangıç durumu reddedici olmalı ve yalnızca çift sayıda harf okunduğunda kabul durumuna geçilmelidir', 'Makine tek durumlu olmalı ve \'b\' harfi okunduğunda girdi bandını doğrudan durdurmalıdır'], 'Bu dil \'a*b*\' düzenli dilidir (eşitlik şartı yoktur!): q0\'da \'a\'lar kalır, \'b\' gelince q1\'e (yine kabul) geçilir ve \'b\'ler q1\'de kalır; q1\'den sonra \'a\' gelirse q_tuzak\'a gidilir.'),
  ('Neden \'a*b*\' dili 3 durumlu basit bir DFA ile tanınabilirken \'a^n b^n\' dili hiçbir DFA ile tanınamaz?', '\'a*b*\' yalnızca sıra kuralını denetlerken \'a^n b^n\' iki harf grubunun adet eşitliğini sınırsız bellekte tutmayı gerektirir', ['\'a*b*\' sonlu sayıda dizge içerirken \'a^n b^n\' sonsuz sayıda dizge içerir', '\'a^n b^n\' ifadesinde boş dizge yer almadığı için başlangıç durumu tanımlanamaz', 'Sonlu durum otomatları üstel ifadeleri içeren sembolleri alfabeye dahil edemez'], 'Her iki dil de sonsuzdur; ancak \'a*b*\' sadece \'b gördükten sonra a gelmesin\' bilgisini (1 bitlik durum) tutarken, \'a^n b^n\' sınırsız n sayısını hatırlamayı şart koşar.'),
  ('Bir derleyicinin sözcüksel analizcisinde \'if\' anahtar kelimesi ile \'ifade\' değişken adını ayırt eden sonlu durum makinesi \'if\' harflerini okuduktan sonra hemen \'ANAHTAR_KELİME\' üretmeyip bir karakter daha ileri bakmasının ilkesi nedir?', 'En uzun eşleşme (maximal munch) kuralı', ['Tembel değerlendirme (lazy evaluation) kuralı', 'Kuyruk özyinelemesi (tail recursion) kuralı', 'Sabit katlama (constant folding) kuralı'], 'Sözcüksel analizcilerde DFA, geçerli bir jeton devam edebildiği sürece okumayı sürdürür (maximal munch); böylece \'ifade\' dizgesi \'if\' + \'ade\' diye yanlış bölünmez.'),
  ('İkili alfabede 4\'e kalansız bölünen negatif olmayan tam sayıları (soldan sağa okunan, \'0\', \'00\', \'100\', \'1100\' vb.) tanıyan bir otomatın yalnızca son iki bite bakması neden yeterlidir?', 'İkili tabanda 2^2 = 4 olduğundan son iki bitin \'00\' olması (veya sayının yalnızca sıfırlardan oluşması) 4\'e bölünmeyi belirler', ['4\'e bölünebilme kuralı ikili tabanda tüm bitlerin toplamının çift olmasına dayanır', 'Dört durumlu her otomat girdi uzunluğundan bağımsız olarak ilk iki biti siler', 'İkili sayılarda çift basamaklı tüm dizgeler her zaman 4\'ün tam katıdır'], 'Onluk tabanda 100\'e bölünmenin son iki basamağa (\'00\') bağlı olması gibi, ikili tabanda 4 = (100)_2 olduğundan değerin 4\'e bölünmesi son iki bitin sıfır olmasına eşdeğerdir.'),
  ('Kenin Thompson tarafından geliştirilen \'Thompson Kurulumu\' (Thompson\'s Construction) algoritmasının girdisi ve çıktısı nedir?', 'Bir düzenli ifadeyi alıp doğrusal sayıda duruma sahip eşdeğer bir ε-NFA üretir', ['Bir bağlamdan bağımsız grameri alıp en küçük deterministik otomata dönüştürür', 'Bir DFA\'daki erişilemez ve eşdeğer durumları birleştirerek minimize eder', 'Kaynak kodu doğrudan hedef işlemcinin makine dili komutlarına çevirir'], 'Thompson kurulumu düzenli ifadedeki birleştirme, seçim (|) ve yıldız (*) işlemlerini yapısal tümevarımla küçük ε-NFA bloklarına dönüştürerek birleştirir.'),
  ('Durum eleme (state elimination) yöntemiyle bir sonlu durum otomatından ne elde edilir?', 'Otomatın tanıdığı dili tam olarak tanımlayan eşdeğer bir düzenli ifade', ['Otomatın yığın belleği kullanan deterministik olmayan yığınlı otomat karşılığı', 'Kaynak kodun soyut sözdizimi ağacı (AST) ve sembol tablosu', 'Girdi dizgesinin ters Polonya gösterimindeki aritmetik sonucu'], 'Kleene teoreminin diğer yönü olan durum eleme yönteminde, ara durumlar tek tek kaldırılırken kenar etiketleri düzenli ifadelerle birleştirilerek sonuç regex\'i bulunur.'),
  ('Bir DFA\'nın kabul durumları kümesi F boş küme (F = ∅) ise bu otomat hangi dili tanır?', 'Hiçbir dizgeyi içermeyen boş dili', ['Yalnızca sıfır uzunluklu boş dizgeden oluşan {ε} dilini', 'Alfabedeki tüm olası dizgeleri kapsayan Σ* evrensel dilini', 'Yalnızca tek karakter uzunluğundaki alfabe sembollerini'], 'Kabul durumu hiç yoksa boş dizge (ε) dahil hiçbir girdi kabul edilemez; bu durum ∅ (boş dil) ile {ε} (boş dizge dili) arasındaki kritik farkı gösterir.'),
  ('Boş dil (∅) ile yalnızca boş dizgeden oluşan dil ({ε}) arasındaki fark sonlu durum otomatında nasıl görülür?', '∅ dilinin otomatında hiç kabul durumu yokken, {ε} dilinin otomatında başlangıç durumu kabul durumudur ve her harf tuzak duruma gider', ['Her iki dil de matematiksel olarak aynı kümeyi gösterdiği için tek durumlu aynı DFA ile çizilir', '{ε} dilinin otomatında hiç başlangıç durumu bulunmazken ∅ dilinde tüm durumlar kabul durumudur', '∅ dili yalnızca NFA ile gösterilebilirken {ε} dili yalnızca yığınlı otomatla gösterilebilir'], '|∅| = 0 elemandır (hiç kabul durumu yok); |{ε}| = 1 elemandır (yalnızca 0 harf okunduğunda kabul verir, 1+ harf okunursa tuzak duruma düşer).'),
  ('Aşağıdaki günlük yaşam sistemlerinden hangisinin davranışı tek başına bir sonlu durum makinesiyle (ek sınırsız sayaç/bellek olmadan) TAM OLARAK modellenemez?', 'Sınırsız sayıda katı olan kuramsal bir gökdelende basılan tüm kat çağrılarını geliş sırasıyla kuyrukta tutan denetleyici', ['Üç kademeli hız ayarı (Kapalı, Düşük, Orta, Yüksek) olan tavan vantilatörü anahtarı', 'Çamaşır makinesinin \'Su Alma -> Yıkama -> Durulama -> Sıkma -> Bitiş\' program döngüsü', 'Mikrodalga fırında kapak açıldığında ısıtmayı durdurup kapandığında devam ettiren güvenlik kilidi'], 'Sabit sayıda durumu olan vantilatör, yıkama aşamaları ve kapak kilidi sonlu durum makinesidir; sınırsız kuyruk ise sonlu durum sayısını aşar.'),
  ('Deterministik sonlu otomatta uzunluğu n olan bir girdi dizgesinin kabul edilip edilmediğini sınamanın zaman ve ek bellek karmaşıklığı nedir?', 'O(n) zaman ve O(1) ek çalışma belleği', ['O(2^n) zaman ve O(n) yığın belleği', 'O(n log n) zaman ve O(n) önbellek dizisi', 'O(n^2) zaman ve O(1) ek çalışma belleği'], 'DFA her karakter için geçiş tablosundan O(1) sürede tek bir sıradaki duruma bakar ve yalnızca \'mevcut durum\' değişkenini tuttuğundan O(1) bellek ve O(n) zamanda çalışır.'),
  ('Bir sonlu durum makinesiyle tasarlanan \'Tam Sayı Sabiti Okuyucu\' başlangıçta isteğe bağlı \'+\' veya \'-\' işareti, ardından en az bir rakam beklemektedir. Başlangıç durumu q0, işaret okunduktan sonraki durum q1, rakam okunduktan sonraki durum q2 ise hangi durum(lar) kabul durumu olmalıdır?', 'Yalnızca q2 durumu', ['Hem q1 hem de q2 durumları', 'q0, q1 ve q2 durumlarının tamamı', 'Yalnızca q0 ve q2 durumları'], 'Tek başına \'+\' veya \'-\' (q1) ya da boş dizge (q0) geçerli bir tam sayı değildir; en az bir rakam okunup q2\'ye geçilmiş olmalıdır.'),
  ('Bir mikrodenetleyici buton okuma devresinde mekanik sıçramayı (switch bounce) filtrelemek için \'Serbest -> Basılma Bekleniyor -> Basılı -> Bırakılma Bekleniyor\' biçiminde 4 durumlu bir FSM kullanılmasının amacı nedir?', 'Milisaniyelik kontak titreşimlerini tek bir temiz basma olayı olarak doğrulayıp sahte çoklu tetiklemeleri engellemek', ['Butona basılma sayısını ikili tabanda kodlayarak kalıcı EEPROM belleğe kaydetmek', 'Analog gerilim seviyesini dijital ses sinyaline dönüştürerek hoparlöre iletmek', 'İşlemcinin saat frekansını buton basılı tutulduğu sürece iki katına çıkarmak'], 'Debouncing FSM\'i sinyal değiştikten sonra kısa bir doğrulama süresi boyunca kararlılığı bekler; böylece mekanik kontak sıçraması yüzlerce basış sayılmaz.'),
  ('Sonlu durum makinesini yazılımda \'if-else / switch-case\' yığınları yerine bir \'Durum Geçiş Tablosu\' (2 boyutlu dizi: tablo[mevcut_durum][girdi]) olarak kodlamanın en önemli mühendislik avantajı nedir?', 'Mantığı veriye dönüştürerek kod karmaşıklığını sabit tutması ve yeni geçiş kurallarının yalnız tabloyu güncelleyerek eklenebilmesi', ['Derleyicinin kaynak kodu sözdizimi analizine sokmadan doğrudan çalıştırmasını sağlaması', 'Programın çalışma zamanındaki bellek kullanımını her zaman sıfır bayta indirmesi', 'Düzenli olmayan bağlamdan bağımsız dillerin de yığınsız çözülmesine olanak tanıması'], 'Tablo güdümlü (table-driven) FSM\'de motor döngüsü birkaç satırdır (\'durum = tablo[durum][sembol]\'); onlarca iç içe koşul bloğu yerine temiz, bakımı kolay ve O(1) erişimli yapı sağlar.'),
  ('NFA durum diyagramında bir q durumundan \'a\' sembolü için hiç çıkış oku çizilmemişse ve girdi olarak \'a\' okunursa o hesaplama dalına ne olur?', 'O hesaplama dalı ölür (reddedilir); varsa diğer paralel dallar çalışmaya devam eder', ['Makine otomatik olarak başlangıç durumuna sıçrayarak dizgeyi baştan okur', 'Okunmayan \'a\' karakteri atlanır ve bir sonraki karakter aynı durumda denenir', 'Tüm paralel dallar anında durdurularak çalışma zamanı istisnası üretilir'], 'NFA\'da eksik geçiş δ(q, a) = ∅ (boş küme) demektir; DFA\'daki açık tuzak durumunun aksine ilgili dal sessizce sonlanır.'),
  ('Altküme kurulumuyla bir NFA\'yı DFA\'ya dönüştürürken NFA\'daki δ(q, a) = ∅ (boş küme) sonucu DFA tarafında neye dönüşür?', 'Tüm alfabe sembollerinde kendi kendisine geçiş yapan tek bir \'∅\' (tuzak) durumuna', ['Doğrudan kabul durumları kümesine dahil edilen yeni bir başlangıç durumuna', 'Girdi dizgesini yarıda kesen donanımsal kesme (interrupt) komutuna', 'Diğer tüm durumlara epsilon geçişi gönderen dağıtıcı düğüme'], 'Kuvvet kümesinin bir elemanı olan boş küme (∅), tam tanımlı DFA\'da hiçbir kabul durumu içermeyen ve her harfte ∅\'ye giden tuzak durumu oluşturur.'),
  ('{0, 1} alfabesinde her \'0\' karakterinden hemen sonra kesinlikle bir \'1\' karakterinin geldiği (örneğin ε, \'111\', \'01\', \'10101\' geçerli; \'0\', \'00\', \'10\' geçersiz) dili tanıyan en küçük DFA\'da \'0\' okunduğu anda geçilen durum kabul durumu olabilir mi?', 'Hayır; dizge o anda biterse son karakter \'0\' kalacağı ve arkasından \'1\' gelmemiş olacağı için ret durumu olmalıdır', ['Evet; çünkü ilk \'0\' okunduğunda kural henüz ihlal edilmemiştir ve tüm önekler kabul edilmelidir', 'Evet; ancak yalnızca girdi dizgesinin toplam uzunluğu çift sayı olduğunda kabul verir', 'Hayır; çünkü \'0\' okunduğu anda makine doğrudan kurtuluşu olmayan tuzak durumuna düşer'], 'Tek \'0\' gördüğümüzde geçilen q1 durumu tuzak değildir (\'1\' gelirse kurtulup kabul durumuna döner), ancak dizge orada biterse \'10\' gibi geçersiz olacağından q1 kabul durumu olamaz!'),
  ('JSON sayı biçiminde \'0\' tek başına geçerliyken \'05\' gibi baştaki sıfırlar geçersizdir; \'1\' ile \'9\' arası rakamlarla başlayan tam sayılar ise (\'105\' gibi) istediği kadar rakamla devam edebilir. İşaretsiz JSON tam sayılarını tanıyan DFA\'da \'0\' ile \'1-9\' başlangıçtan itibaren neden iki farklı kabul durumuna ayrılmalıdır?', '\'0\' kabul durumundan sonra başka rakam gelirse reddedilmeli, \'1-9\' kabul durumundan sonra rakam gelirse kabulde kalmalıdır', ['\'0\' karakteri ASCII tablosunda harflerden sonra yer aldığı için ayrı bir yığın gerektirir', 'JSON standardında çift sayılar ve tek sayılar farklı veri tiplerinde saklanır', 'Sonlu durum makinelerinde tek bir duruma birden fazla rakam geçişi yazılamaz'], '\'0\' ve \'1\' ikisi de tek basamaklı geçerli sayılardır ama devam davranışları farklıdır (\'0\' + rakam -> hata; \'1\' + rakam -> geçerli), bu yüzden Myhill-Nerode gereği ayrı durumlardır.'),
  ('Bir akıllı ev termostatında ısıtıcı tam 20.0 °C sınırında açılıp kapanacak şekilde tek eşikli tasarlansaydı sensör gürültüsüyle sürekli aç-kapa yapardı. Bunu önlemek için \'Isıtma Açık\' durumundan \'Kapalı\'ya 20.5 °C\'de, \'Kapalı\'dan \'Isıtma Açık\'a 19.5 °C\'de geçilmesi hangi durum makinesi ilkesidir?', 'Histerezis (gecikmeli çift eşikli durum geçişi)', ['Epsilon kapanışı (boş girdili durum birleştirme)', 'Özyinelemeli geri izleme (recursive backtracking)', 'Belirsiz gramer ayrıştırması (ambiguous parsing)'], 'Histerezis, sistemin mevcut durumuna (\'Açık\' mı \'Kapalı\' mı) bağlı olarak farklı geçiş eşikleri kullanır; sıcaklık 20.0 °C iken ısıtıcının ne yapacağını geçmiş durumu belirler.'),
  ('Deterministik bir sonlu otomatta başlangıç durumu q0, girdi dizgeleri x ve y için genişletilmiş geçiş fonksiyonu δ*(q0, xy) nasıl hesaplanır?', 'Önce x dizgesi okunarak ulaşılan p = δ*(q0, x) durumu bulunur, ardından bu p durumundan y dizgesi okunarak δ*(p, y) hesaplanır', ['Hem x hem de y dizgeleri ayrı ayrı q0 başlangıç durumundan okunup sonuç durumlarının kesişimi alınır', 'Önce y dizgesi sondan başa doğru okunur, ardından x dizgesi yığın belleğine eklenir', 'x ve y dizgelerinin uzunlukları çarpılarak geçiş tablosunda modüler indeksleme yapılır'], 'Genişletilmiş geçiş fonksiyonunun temel özelliği δ*(q, xy) = δ*(δ*(q, x), y) olmasıdır; geçmiş tüm x girdisinin özeti yalnızca ulaşılan p durumunda saklıdır.'),
  ('Oyun programlamada bir karakterin aynı anda hem hareket durumunu (\'Duruyor / Koşuyor / Zıplıyor\') hem de silah durumunu (\'Boşta / Ateş Ediyor / Şarjör Değiştiriyor\') tek bir düz FSM\'de 3 x 3 = 9 birleşik durumla tutmak yerine iki paralel (dik / orthogonal) durum makinesi kullanmanın yararı nedir?', 'Durum sayısını çarpımsal (m · n) büyümekten kurtararak toplamsal (m + n) düzeyde yönetilebilir kılması', ['Karakterin aynı anda hem koşup hem şarjör değiştirmesini donanım düzeyinde engellemesi', 'Oyun motorunun kare hızını (FPS) karakterin hızıyla doğru orantılı artırması', 'Bellekteki tüm değişkenlerin derleme zamanında sabitlere dönüştürülmesini sağlaması'], 'Bağımsız alt davranışlar paralel bölgelerle modellendiğinde yeni bir hareket ve yeni bir silah durumu eklemek m·n kombinasyon patlaması yaratmaz.'),
  ('Kuyruk özyinelemesi (tail recursion) kavramını standart özyinelemeden ayıran temel yapısal özellik nedir?', 'Özyinelemeli çağrının fonksiyondaki en son işlem olması ve dönüş değerinin üzerinde ek hesaplama yapılmaması', ['Fonksiyonun kendi kendini çağırmak yerine yardımcı başka bir fonksiyonla karşılıklı çağrılaşması', 'Girdi dizisinin her zaman ilk eleman yerine en sondaki elemanından bölünerek işlenmesi', 'Taban durum kontrolünün fonksiyonun en başında değil en son satırında yer alması'], '\'return f(n-1, birikim * n)\' kuyruk özyinelemelidir; buna karşılık \'return n * f(n-1)\' dönüşten sonra çarpma beklediği için kuyruk özyinelemeli değildir.'),
  ('Kuyruk çağrısı eniyilemesini (Tail Call Optimization - TCO) destekleyen bir derleyici kuyruk özyinelemeli fonksiyonu nasıl çalıştırır?', 'Yeni yığın çerçevesi açmak yerine mevcut çerçeveyi güncelleyip döngü gibi O(1) ek bellekle çalıştırır', ['Tüm ara sonuçları disk üzerindeki geçici bir dosyaya yazarak RAM kullanımını azaltır', 'Çağrıları otomatik olarak çok çekirdekli işlemcide paralel iş parçacıklarına böler', 'Fonksiyonu derleme zamanında sabit bir arama tablosuna dönüştürerek özyinelemeyi siler'], 'Geri dönüşte yapılacak ek işlem kalmadığından mevcut yığın çerçevesinin korunmasına gerek yoktur; derleyici çağrıyı bir sıçrama (jump) komutuna çevirir.'),
  ('Standart \'return n * faktoriyel(n - 1)\' fonksiyonunu kuyruk özyinelemeli hale getirmek için yaygın olarak hangi programlama tekniği kullanılır?', 'Ara çarpım sonucunu bir sonraki çağrıya taşıyan biriktirici (accumulator) parametresi eklemek', ['Çarpma operatörü yerine tekrarlı toplama yapan ikinci bir iç özyineleme kurmak', 'Yerel değişkenlerin tümünü statik veya küresel (global) dizi olarak tanımlamak', 'Taban durumu n == 0 yerine n == 100 gibi bir üst sınıra taşımak'], '\'faktoriyel(n, birikim): n <= 1 ise birikim döndür; değilse faktoriyel(n - 1, n * birikim)\' şeklinde yazıldığında dönüşte bekleyen işlem kalmaz.'),
  ('Saf özyinelemeli Fibonacci tanımı olan \'fib(n) = fib(n-1) + fib(n-2)\' (fib(0)=0, fib(1)=1) ile fib(5) hesaplanırken fib(2) fonksiyonu toplam kaç kez çağrılır?', '3 kez', ['1 kez', '2 kez', '5 kez'], 'fib(5) -> fib(4)+fib(3); fib(4) -> fib(3)+fib(2); iki adet fib(3) ise birer kez fib(2) çağırır; böylece fib(2) toplam 1 + 2 = 3 kez hesaplanır.'),
  ('Hanoi Kuleleri bulmacasında n diski kurallara uygun biçimde kaynak çubuktan hedef çubuğa taşımak için gereken minimum hamle sayısını veren özyineleme bağıntısı ve kapalı çözümü nedir?', 'T(n) = 2·T(n - 1) + 1 ve toplam 2^n - 1 hamle', ['T(n) = T(n - 1) + n ve toplam n(n + 1)/2 hamle', 'T(n) = 3·T(n - 1) ve toplam 3^n hamle', 'T(n) = 2·T(n / 2) + n ve toplam n·log2(n) hamle'], 'Üstteki n-1 disk yardımcı çubuğa taşınır (T(n-1)), en büyük disk hedefe konur (+1) ve n-1 disk yardımcından hedefe taşınır (T(n-1)); çözüm 2^n - 1\'dir.'),
  ('Ackermann fonksiyonundaki \'A(m, n) = A(m - 1, A(m, n - 1))\' veya McCarthy 91 fonksiyonundaki \'M(n) = M(M(n + 11))\' ifadeleri hangi özyineleme türüne örnektir?', 'İç içe özyineleme (nested recursion)', ['Kuyruk özyinelemesi (tail recursion)', 'İkili arama özyinelemesi (binary recursion)', 'Karşılıklı özyineleme (mutual recursion)'], 'Fonksiyonun kendi argümanlarından birinin bizzat kendisinin özyinelemeli bir çağrı olması durumuna iç içe özyineleme (nested recursion) denir.'),
  ('Böl ve Yönet (Divide and Conquer) algoritmalarından Birleştirmeli Sıralama (Merge Sort) için geçerli olan T(n) = 2·T(n/2) + O(n) özyineleme bağıntısının asimptotik çözümü nedir?', 'O(n log n)', ['O(n^2)', 'O(n)', 'O(2^n)'], 'Her seviyede toplam O(n) birleştirme işi yapılır ve özyineleme ağacının yüksekliği log2(n) olduğundan toplam zaman O(n log n) olur.'),
  ('Bir dizgeyi ters çeviren özyinelemeli ters(s) fonksiyonu \'eğer uzunluk(s) <= 1 ise s döndür; değilse ters(s[1..son]) + s[0] döndür\' şeklinde yazılmıştır. ters("KALE") çağrısında çağrı yığını en derin noktadayken ilk dönen taban durum değeri nedir?', '"E"', ['"K"', '"ELAK"', '"LA"'], 'Çağrılar sırasıyla ters("KALE") -> ters("ALE") -> ters("LE") -> ters("E") şeklinde iner; taban duruma ulaşan en iç çağrı tek harfli "E" dizgesini döndürür.'),
  ('Aşağıdaki C/Java benzeri özyinelemeli yazdir(n) fonksiyonu \'if (n <= 0) return; print(n); yazdir(n - 1); print(n);\' biçimindedir. yazdir(3) çağrıldığında ekrana hangi çıktı dizisi basılır?', '3 2 1 1 2 3', ['3 2 1 3 2 1', '1 2 3 3 2 1', '3 3 2 2 1 1'], 'Özyinelemeli çağrıdan önceki print(n) iniş yolunda \'3 2 1\' basar; çağrıdan sonraki print(n) ise yığın çözülürken çıkış yolunda ters sırayla \'1 2 3\' basar.'),
  ('Özyinelemeli bir fonksiyonda \'print\' işlemini özyinelemeli çağrının ÖNÜNE koymak ile ARKASINA koymak arasındaki temel fark nedir?', 'Önüne konduğunda işlemler çağrı sırasıyla (yukarıdan aşağı), arkasına konduğunda yığından dönüş sırasıyla (ters sırada) yürütülür', ['Arkasına konan ifadeler ölü kod sayıldığı için derleyici tarafından hiçbir zaman çalıştırılmaz', 'Önüne konduğunda zaman karmaşıklığı O(n) iken arkasına konduğunda O(2^n) olur', 'Arkasına konduğunda fonksiyon taban duruma ihtiyaç duymadan kendiliğinden durur'], 'Özyineleme öncesi (pre-order) işlemler yığın büyürken, özyineleme sonrası (post-order) işlemler ise yığın geri sarılarak çözülürken (unwinding) çalışır.'),
  ('Pozitif bir tam sayıyı ikili (binary) tabanda ekrana basan \'ikiliYaz(n): eğer n > 1 ise ikiliYaz(n // 2); yazdir(n % 2)\' fonksiyonuna ikiliYaz(13) verildiğinde neden basamaklar doğru sırada (\'1101\') yazılır?', 'Kalanları basan satır özyinelemeden sonra geldiği için en son bulunan en anlamlı bit yığından ilk olarak ekrana basılır', ['Tam sayı bölme operatörü sayıyı soldan sağa doğru basamaklarına ayırarak ilerler', 'Mod alma işlemi yalnızca çift sayılarda sıfır ürettiği için bit sırasını kendiliğinden düzeltir', 'Fonksiyon kuyruk özyinelemeli olduğu için sonuçları öbek belleğinde sıralar'], '13 -> 6 -> 3 -> 1 inişinde kalanlar (1, 0, 1, 1) yığında bekler; en dipteki 1 ilk basılır ve dönüş yolunda 1, 1, 0, 1 sırasıyla doğru ikili gösterim elde edilir.'),
  ('Bir ikili ağacın yüksekliğini (kökten en uzak yaprağa olan kenar veya düğüm derinliğini) bulan \'1 + max(yukseklik(sol), yukseklik(sag))\' algoritmasında n düğümlü tamamen sağa yatık (çizgisel) bir ağaç ile tam dengeli bir ağacın maksimum çağrı yığını derinlikleri sırasıyla nedir?', 'Sağa yatık ağaçta O(n), tam dengeli ağaçta O(log n)', ['Her iki ağaçta da düğüm sayısı kadar O(n)', 'Sağa yatık ağaçta O(1), tam dengeli ağaçta O(n)', 'Her iki ağaçta da sabit O(log n)'], 'Ağaç üzerinde özyinelemeli dolaşmanın anlık yığın belleği ağacın yüksekliği O(h) kadardır; dengeli ağaçta h = log n iken dejenere çizgisel ağaçta h = n olur.'),
  ('Geri izleme (backtracking) yöntemiyle çözülen N-Vezir veya Sudoku gibi problemlerde özyinelemeli çağrı başarısız olup geri döndüğünde yapılması zorunlu adım nedir?', 'Çağrıdan önce tahtada yapılan son geçici seçimi geri alarak durumu eski haline getirmek', ['Taban durumu devre dışı bırakarak tahtanın boyutunu bir birim büyütmek', 'O ana kadar bulunan tüm geçerli çözümleri bellekten tamamen silmek', 'Çağrı yığınındaki en alt çerçeveye doğrudan sıçrayarak programı sonlandırmak'], 'Paylaşılan bir tahta/dizi durumu üzerinde çalışırken bir dal başarısız olduğunda, sıradaki alternatif dalı denemeden önce yapılan değişiklik geri alınmalıdır.'),
  ('Bir kümenin tüm alt kümelerini (kuvvet kümesini) üreten özyinelemeli algoritma her eleman için \'elemanı alt kümeye dahil et\' ve \'dahil etme\' şeklinde iki özyinelemeli çağrı yapar. 5 elemanlı bir küme için taban duruma kaç kez ulaşılır?', '32 kez', ['25 kez', '10 kez', '120 kez'], 'Her eleman için 2 bağımsız karar verildiğinden 5 seviyeli karar ağacının yapraklarında 2^5 = 32 farklı alt küme (taban durum) üretilir.'),
  ('Bir Labirent Çözme (veya Resimdeki Boya Doldurma - Flood Fill) algoritması komşu 4 hücreye (yukarı, aşağı, sol, sağ) özyinelemeli çağrı yaparken \'ziyaret edildi\' işaretlemesini unutursa ne olur?', 'İki komşu boş hücre arasında ileri-geri sonsuz özyinelemeye girerek yığın taşması üretir', ['Labirentteki en kısa yol yerine en uzun yolu bularak normal şekilde sonlanır', 'Yalnızca sağa ve aşağıya giderek labirentin sol üst yarısını taramadan bırakır', 'Zaman karmaşıklığı O(V) yerine O(V log V) düzeyine çıkarak biraz yavaşlar'], 'Ağaçların aksine ızgara ve çizgelerde döngüler vardır: A hücresi komşusu B\'yi, B hücresi de tekrar komşusu A\'yı çağıracağı için ziyaret işareti olmadan sonsuz çağrı oluşur.'),
  ('Pascal üçgenindeki binom katsayısını \'C(n, k) = C(n-1, k-1) + C(n-1, k)\' özyinelemesiyle hesaplayan bir fonksiyonda hangi koşullar taban durum (1 döndüren durum) olarak tanımlanmalıdır?', 'k == 0 veya k == n olması', ['Yalnızca n == 0 ve k == 1 olması', 'k == 1 veya n == k - 1 olması', 'n == 2 * k eşitliğinin sağlanması'], 'Pascal üçgeninin sol kenarı (k == 0, hiç eleman seçmeme) ve sağ kenarı (k == n, tüm elemanları seçme) her zaman 1 değerindedir ve özyinelemeyi sınırlar.'),
  ('f(n) fonksiyonu \'if (n <= 1) return 0; return 1 + f(n / 2);\' (tam sayı bölmesiyle) olarak yazıldığında f(32) ve f(35) çağrılarının döndürdüğü sonuçlar sırasıyla nedir?', '5 ve 5', ['5 ve 6', '6 ve 6', '16 ve 17'], 'Bu fonksiyon taban 2\'de logaritmanın tam kısmını (⌊log2(n)⌋) hesaplar: 32->16->8->4->2->1 (5 adım) ve 35->17->8->4->2->1 (yine 5 adım).'),
  ('Bir ağacın tamamını bellekten güvenli biçimde serbest bırakmak (free/delete) gerektiğinde çocuk işaretçilerini kaybetmemek için hangi özyinelemeli dolaşma sırası ZORUNLUDUR?', 'Son-sıralı dolaşma (Post-order: önce Sol alt ağaç, sonra Sağ alt ağaç, en son Kök)', ['Ön-sıralı dolaşma (Pre-order: önce Kök silinir, sonra Sol ve Sağ alt ağaçlara gidilir)', 'İç-sıralı dolaşma (In-order: önce Sol silinir, sonra Kök silinir, oradan Sağa geçilir)', 'Rastgele özyinelemeli seçim (her adımda kök veya yapraktan biri silinir)'], 'Kök düğüm çocuklarından önce silinirse \'kök->sağ\' işaretçisine erişim kaybolur (use-after-free / bellek sızıntısı); bu yüzden önce alt ağaçlar silinmeli, en son kök silinmelidir.'),
  ('Matematiksel tümevarım (mathematical induction) ile özyinelemeli algoritma tasarımı arasındaki doğrudan yapısal eşleşme hangisidir?', 'Tümevarımın başlangıç adımı özyinelemenin taban durumuna, tümevarım hipotezi ve adımı ise özyinelemeli çağrıya karşılık gelir', ['Tümevarım yalnızca sonsuz kümelerde geçerliyken özyineleme yalnızca sabit boyutlu dizilerde çalışır', 'Tümevarımın başlangıç adımı yığın taşmasını, tümevarım adımı ise sözdizimi analizini temsil eder', 'Tümevarım aşağıdan yukarıya çalışırken özyineleme hiçbir zaman alt problemlere bölünmez'], 'Özyinelemeli fonksiyonun doğruluğu tümevarımla kanıtlanır: taban durum doğruysa ve küçültülmüş alt çağrının doğru sonuç verdiği varsayımıyla (hipotez) mevcut adım doğruysa algoritma doğrudur.'),
  ('Sıralı iki bağlı listeyi (L1 ve L2) tek bir sıralı bağlı liste halinde birleştiren özyinelemeli \'birlestir(L1, L2)\' fonksiyonunda L1.deger <= L2.deger olduğunda hangi işlem yapılır?', 'L1.sonraki = birlestir(L1.sonraki, L2) atanır ve L1 düğümü döndürülür', ['L2.sonraki = birlestir(L1, L2.sonraki) atanır ve L2 düğümü döndürülür', 'L1.sonraki = L2 atanarak özyineleme hemen sonlandırılır ve L1 döndürülür', 'Yeni bir dizi oluşturularak tüm elemanlar kabarcık sıralamayla dizilir'], 'Daha küçük olan L1 başa seçilir, onun geri kalan kuyruğu ise \'L1.sonraki\' ile \'L2\'nin özyinelemeli birleşimine bağlanır.'),
  ('Özyinelemeli bir fonksiyonun içinde statik (static) veya küresel (global) bir sayaç değişkeni kullanmanın çok iş parçacıklı (multi-threaded) veya yeniden çağrılabilir kodda yarattığı temel tehlike nedir?', 'Tüm özyineleme çerçeveleri aynı bellek hücresini paylaştığı için yeniden girişli olma (reentrancy) özelliğini bozar ve yan etki yaratır', ['Statik değişkenler her özyinelemeli çağrıda yeniden sıfırlandığı için önceki değerleri tutamaz', 'Derleyici küresel değişken gören özyinelemeli fonksiyonları derlemeyi güvenlik nedeniyle reddeder', 'Yığın çerçevesinin boyutunu her adımda ikiye katlayarak O(2^n) bellek tüketimine yol açar'], 'Yerel değişkenler her çerçevede bağımsız kopyalanırken statik/küresel değişken tektir; fonksiyon tekrar çağrıldığında veya paralel çalıştığında eski değerler birbirini ezer.'),
  ('Bir dizideki en büyük elemanı bulan özyinelemeli \'enBuyuk(dizi, n)\' (ilk n elemanın maksimumu) fonksiyonunun taban durumu ve özyineleme adımı nasıl kurulmalıdır?', 'n == 1 ise dizi[0] döndür; değilse max(dizi[n - 1], enBuyuk(dizi, n - 1)) döndür', ['n == 0 ise 0 döndür; değilse max(dizi[n - 1], enBuyuk(dizi, n - 1)) döndür', 'n == 1 ise 1 döndür; değilse dizi[n - 1] + enBuyuk(dizi, n - 1) döndür', 'n == 2 ise dizi[1] döndür; değilse min(dizi[0], enBuyuk(dizi, n / 2)) döndür'], 'Yanlışlıkla \'n == 0 ise 0 döndür\' yazılırsa tüm elemanları negatif olan \'[-5, -2, -9]\' gibi bir dizide hatalı olarak 0 döner; tek elemanlı taban durum \'dizi[0]\' her işaret için güvenlidir!'),
  ('Yığın (stack) tabanlı bir RPN hesaplayıcısında \'8 2 /\' ifadesi değerlendirilirken çıkarma ve bölme gibi değişme özelliği olmayan işlemlerde yığından çekilen elemanların sırası neden kritiktir?', 'Yığından ilk çekilen (üstteki) eleman sağ işlenen (bölen = 2), ikinci çekilen eleman ise sol işlenen (bölünen = 8) olduğu için', ['Yığından ilk çekilen eleman her zaman sol işlenen olduğundan \'8 / 2\' yerine doğrudan \'8 * 2\' yapılır', 'LIFO yığınında elemanlar küçükten büyüğe sıralandığı için her zaman büyük sayı küçük sayıya bölünür', 'Bölme operatörü yığından üç eleman çekip ortadaki elemanı sonuç olarak geri iter'], '\'8\' sonra \'2\' itildiğinde yığının tepesinde \'2\' vardır; ilk pop() sağ işleneni (b = 2), ikinci pop() sol işleneni (a = 8) verir ve işlem \'a / b = 8 / 2 = 4\' olarak uygulanmalıdır!'),
  ('Ters Polonya Gösteriminde (RPN) verilen \'5 1 2 + 4 * + 3 -\' ifadesinin sayısal değeri kaçtır?', '14', ['21', '11', '29'], 'Adım adım: \'1 2 +\' -> 3 (yığın: 5, 3); \'4 *\' -> 3*4=12 (yığın: 5, 12); \'+\' -> 5+12=17 (yığın: 17); \'3 -\' -> 17-3 = 14.'),
  ('Ters Polonya Gösteriminde verilen \'10 6 9 3 + -11 * / * 17 + 5 +\' ifadesinde tam sayı bölmesi (sıfıra doğru kesme) uygulandığında \'9 3 +\' işleminden hemen sonra yığındaki elemanlar tabandan tepeye doğru nasıldır?', '10, 6, 12', ['10, 15, 3', '16, 9, 3', '10, 6, 27'], '10, 6, 9, 3 sırasıyla yığına itilir; \'+\' operatörü üstteki 9 ve 3\'ü çekip 12 iter ve yığında tabandan tepeye [10, 6, 12] kalır.'),
  ('İçtakı (infix) bir ifade Manevra İstasyonu algoritmasıyla RPN\'e dönüştürülürken değişkenlerin kendi aralarındaki soldan sağa görünüm sırası (örneğin A, B, C, D) nasıl değişir?', 'Değişkenlerin kendi aralarındaki göreli sırası birebir aynı kalır; yalnızca operatörler yer değiştirir ve parantezler kalkar', ['Parantez içindeki değişkenler her zaman ifadenin en soluna taşınır', 'Yüksek öncelikli operatörün sağındaki değişken solundakinin önüne geçer', 'Tüm değişkenlerin sırası yığın yüzünden tamamen tersine (D, C, B, A) döner'], 'Önemli özellik: hem içtakı \'(A + B) * (C - D)\' hem de RPN \'A B + C D - *\' ifadesinde işlenenlerin sırası A, B, C, D olarak korunur!'),
  ('Soldan birleşmeli (left-associative) çıkarma operatörü içeren \'10 - 4 - 2\' içtakı ifadesinin doğru RPN karşılığı hangisidir ve yanlış birleşme seçilirse sonuç nasıl sapar?', '\'10 4 - 2 -\' olup sonucu 4\'tür; sağdan birleştirilirse \'10 4 2 - -\' olur ve 8 gibi hatalı sonuç üretir', ['\'10 4 2 - -\' olup sonucu 4\'tür; soldan birleştirilirse \'10 4 - 2 -\' olur ve 8 üretir', '\'10 4 - 2 +\' olup eksi işaretleri birbirini artıya dönüştürerek 8 sonucunu verir', 'Her iki RPN dizilimi de çıkarma işleminde birleşme özelliğinden dolayı 4 sonucunu üretir'], 'Çıkarma soldan birleşmelidir: (10 - 4) - 2 = 4 -> RPN \'10 4 - 2 -\'. Sağdan birleşseydi 10 - (4 - 2) = 8 -> \'10 4 2 - -\' olurdu.'),
  ('Manevra İstasyonu algoritmasında girdi dizgesinde kapanış parantezi \')\' okunduğunda operatör yığını üzerinde hangi işlem gerçekleştirilir?', 'Eşleşen açılış parantezi \'(\' görülene kadar yığındaki operatörler çekilip çıktıya eklenir, ardından \'(\' yığından atılır', ['Açılış parantezi ve kapanış parantezi de dahil olmak üzere tüm semboller çıktıya yazılır', 'Yığının tamamı tabana kadar boşaltılır ve açıkta kalan tüm parantezler sıfırlanır', 'Kapanış parantezi en yüksek öncelikli operatör olarak yığının en tepesine itilir'], 'Parantezler RPN çıktısında yer almaz; \')\' geldiğinde \'(\' işaretine kadar bekleyen alt ifade operatörleri çıktıya boşaltılır ve \'(\' çıktıya yazılmadan düşürülür.'),
  ('Manevra İstasyonu algoritmasında \')\' okunduğunda operatör yığını tamamen boşalana kadar hiç \'(\' karakterine rastlanmazsa bu durum neyi kanıtlar?', 'Girdi ifadesinde karşılığı olmayan fazladan bir kapanış parantezi (dengesiz parantez hatası) bulunduğunu', ['İfadenin zaten RPN biçiminde yazılmış olduğunu ve dönüşüme gerek kalmadığını', 'Tüm operatörlerin sağdan birleşmeli olarak tanımlandığını', 'Çıktı kuyruğunun kapasitesinin dolup yeniden boyutlandırılması gerektiğini'], 'Her \')\' için yığında daha önce itilmiş bir \'(\' bulunmalıdır; yığın \'(\' bulamadan biterse ya da girdi sonunda yığında hâlâ \'(\' kalırsa parantezler dengesizdir.'),
  ('Yalnızca ikili (binary, 2 işlenen alan) operatörler ve sayılardan oluşan GEÇERLİ bir RPN ifadesinde toplam N adet sayı (işlenen) varsa toplam kaç adet ikili operatör bulunmak zorundadır?', 'N - 1 adet', ['N adet', 'N + 1 adet', '2N - 1 adet'], 'Her sayı yığın derinliğini +1 artırır, her ikili operatör 2 çekip 1 iterek net derinliği -1 azaltır; sonunda yığında tam 1 sonuç kalması için N - M = 1 yani M = N - 1 olmalıdır.'),
  ('Aşağıdaki RPN ifadelerinden hangisi sözdizimsel olarak GEÇERSİZDİR?', '4 5 + * 2', ['4 5 2 * +', '4 5 + 2 *', '4 5 2 + *'], '\'4 5 +\' işleminden sonra yığında tek bir eleman (9) kalır; hemen ardından gelen ikili \'*\' operatörü iki işlenen beklediği için yığın alt taşması (underflow) hatası oluşur.'),
  ('Önek (prefix) biçiminde verilen \'- * + 3 4 5 6\' ifadesinin sayısal sonucu kaçtır?', '29', ['23', '17', '11'], 'Sağdan sola (veya içten dışa): \'+ 3 4\' = 7; \'* 7 5\' = 35; \'- 35 6\' = 29 (\'((3 + 4) * 5) - 6\' ifadesine karşılık gelir).'),
  ('Bir aritmetik ifadeyi temsil eden İkili İfade Ağacı (Binary Expression Tree) üzerinde Önek (Prefix), İçtakı (Infix) ve Sonek (Postfix / RPN) gösterimleri sırasıyla hangi ağaç dolaşma yöntemlerine karşılık gelir?', 'Ön-sıralı (Pre-order), İç-sıralı (In-order) ve Son-sıralı (Post-order) dolaşma', ['İç-sıralı (In-order), Ön-sıralı (Pre-order) ve Seviye-sıralı (Level-order) dolaşma', 'Son-sıralı (Post-order), İç-sıralı (In-order) ve Ön-sıralı (Pre-order) dolaşma', 'Seviye-sıralı (Level-order), Son-sıralı (Post-order) ve İç-sıralı (In-order) dolaşma'], 'İfade ağacında yapraklar sayıları, iç düğümler operatörleri tutar: Kök-Sol-Sağ (Pre-order) önek, Sol-Kök-Sağ (In-order, parantezli) içtakı, Sol-Sağ-Kök (Post-order) ise tam olarak RPN üretir!'),
  ('RPN biçimindeki bir dizgeden İkili İfade Ağacı (Expression Tree) oluşturmak için kullanılan yığın algoritmasında ikili bir operatör (örneğin \'*\') okunduğunda ne yapılır?', 'Yığından iki alt ağaç düğümü çekilir (ilki sağ çocuk, ikincisi sol çocuk yapılır), \'*\' kök düğümüne bağlanıp bu yeni ağaç tekrar yığına itilir', ['\'*\' düğümü doğrudan yığının en altındaki sayı düğümünün sol çocuğu olarak eklenir', 'Yığındaki tüm düğümler çekilip tek bir düz bağlı liste halinde \'*\' düğümüne bağlanır', 'Önce iki sayı okunana kadar \'*\' operatörü geçici bir yan kuyrukta bekletilir'], 'RPN\'den ifade ağacı kurmak RPN hesaplamakla aynıdır; tek fark sayısal işlem yapmak yerine sağ ve sol alt ağaçları bağlayıp yeni kök düğüm referansını yığına itmektir.'),
  ('Java Sanal Makinesi (JVM Bytecode), WebAssembly ve Forth programlama dili gibi sistemlerin sanal makine komut kümesinde yazmaç (register) yerine Yığın Makinesi (Stack Machine / RPN mantığı) kullanmasının temel tasarım avantajı nedir?', 'Komutların içinde kaynak ve hedef yazmaç adresleri belirtmek gerekmediği için bayt kodunun çok kompakt ve donanımdan bağımsız olması', ['Yığın makinelerinde aritmetik işlemlerin hiçbir zaman RAM belleğe erişmeden yalnız diskte yapılması', 'Bir toplama işlemi için gereken toplam sanal komut sayısının yazmaç makinelerinden her zaman daha az olması', 'Döngü ve koşullu dallanma komutlarına ihtiyaç duyulmadan tüm programların düz çizgide çalışması'], 'Sıfır adresli (zero-address) yığın komutlarında örneğin JVM\'deki \'iadd\' komutu tek bayttır; işlenenlerin nerede olduğu belli olduğundan (\'yığının en üst iki elemanı\') kod taşınabilir ve küçüktür.'),
  ('Yığın tabanlı bir sanal makinede \'PUSH 7\', \'PUSH 3\', \'DUP\', \'MUL\', \'ADD\' komut dizisi çalıştırıldığında (\'DUP\' en üstteki elemanı kopyalayıp tekrar iter) yığının tepesinde kalan sonuç nedir?', '16', ['30', '100', '24'], 'PUSH 7 -> [7]; PUSH 3 -> [7, 3]; DUP -> [7, 3, 3]; MUL -> [7, 9]; ADD -> [16] sonucu elde edilir.'),
  ('İçtakı biçiminde verilen \'A + B * C - D / E\' ifadesinin RPN (sonek) karşılığı aşağıdakilerden hangisidir?', 'A B C * + D E / -', ['A B + C * D - E /', 'A B C * D E / - +', 'A B C + * D E - /'], 'Önce \'B * C\' (\'B C *\'), sonra soldan birleşmeyle \'A\' ile toplamı (\'A B C * +\'), ardından \'D / E\' (\'D E /\') ve son olarak fark işlemi (\'-\') uygulanır.'),
  ('\'3 4 + 5 6 + *\' RPN ifadesi değerlendirilirken çalışma boyunca yığında aynı anda bulunan MAKSİMUM eleman sayısı kaç olur?', '3 eleman', ['4 eleman', '2 eleman', '6 eleman'], '3 -> [3] (1); 4 -> [3,4] (2); + -> [7] (1); 5 -> [7,5] (2); 6 -> [7,5,6] (3 - zirve!); + -> [7,11] (2); * -> [77] (1). Maksimum derinlik 3\'tür.'),
  ('Mantıksal (Boolean) bir RPN ifadesi olan \'DOĞRU YANLIŞ DEĞİL VE YANLIŞ VEYA\' (\'DEĞİL\' tekli, \'VE\'/\'VEYA\' ikili operatör) değerlendirildiğinde sonuç nedir?', 'DOĞRU', ['YANLIŞ', 'Belirsiz', 'Boş yığın'], 'Yığın: [DOĞRU, YANLIŞ]; \'DEĞİL\' tek eleman çekip tersler -> [DOĞRU, DOĞRU]; \'VE\' -> [DOĞRU]; [DOĞRU, YANLIŞ]; \'VEYA\' -> DOĞRU.'),
  ('Derleyicileri \'Ön Uç (Front-End)\', \'Orta Uç (Middle-End / IR)\' ve \'Arka Uç (Back-End)\' olarak katmanlı tasarlamanın M farklı programlama dilini N farklı işlemci mimarisine derlerken sağladığı en büyük mimari kazanç nedir?', 'M × N adet ayrı derleyici yazmak yerine ortak bir Ara Temsil (IR) etrafında M ön uç + N arka uç (M + N bileşen) yazılmasını sağlaması', ['Kaynak koddaki tüm sözdizimi hatalarının işlemci donanımı tarafından otomatik onarılmasını sağlaması', 'Sembol tablosuna olan ihtiyacı ortadan kaldırarak derleme süresini sabit O(1) zamana indirmesi', 'Farklı programlama dillerinin aynı kaynak dosya içinde satır satır karıştırılarak yazılmasını zorunlu kılması'], 'LLVM ve GCC bu ilkeyle çalışır: C, Rust, Swift gibi dillerin ön uçları aynı LLVM IR ara kodunu üretir; x86, ARM, RISC-V arka uçları ise yalnızca bu IR\'ı hedef makineye çevirir.'),
  ('Sözcüksel analizde \'jeton (token)\' ile \'sözlükbirim (lexeme)\' kavramları arasındaki fark nedir? (\'int sayac = 42;\' örneği üzerinden)', 'Jeton soyut kategoriyi (örneğin TANIMLAYICI / ID), sözlükbirim ise kaynak koddaki gerçek karakter dizisini (\'sayac\') ifade eder', ['Jeton kaynak koddaki yorum satırlarını, sözlükbirim ise yalnızca sayısal sabitleri gösterir', 'Sözlükbirim soyut gramer kuralını, jeton ise işlemcinin makine komutunu temsil eder', 'İki kavram birbirinin tam eşanlamlısıdır ve aralarında hiçbir ayrım bulunmaz'], '\'sayac\' metni sözlükbirimdir (lexeme); derleyicinin onu sınıflandırdığı <TANIMLAYICI, sembol_tablosu_indisi> çifti ise jetondur (token).'),
  ('Aşağıdaki kaynak kod hatalarından hangisi Sözdizimi Analizcisine (Parser) bile ulaşmadan doğrudan Sözcüksel Analizci (Lexer) aşamasında yakalanır?', 'Kaynak kodda dilin alfabesinde tanımlı olmayan geçersiz bir karakter (örneğin C kodunda ifade ortasında \'@\' sembolü) veya kapatılmamış dizge sabiti bulunması', ['İki tam sayı değişkeninin toplanıp sonucu dizge (string) tipindeki bir değişkene atanması', 'Bir \'while\' döngüsünün koşul parantezi açıldığı halde kapanış parantezinin unutulması', 'Tanımlanmamış bir değişken adının aritmetik ifade içinde kullanılması'], 'Kapanmamış parantez sözdizimi (parser) hatasıdır; tip uyuşmazlığı ve tanımsız değişken ise anlamsal (semantic) hatadır! Geçersiz karakter/kapanmamış tırnak ise sözcüksel hatadır.'),
  ('\'int x = "merhaba" + 5;\' gibi parantezleri, operatörleri ve noktalı virgülü gramer kurallarına tamamen uyan bir C/Java satırındaki hata derleyicinin hangi aşamasında tespit edilir?', 'Anlamsal Analiz (Semantic Analysis / Tip Denetimi) aşamasında', ['Sözcüksel Analiz (Lexical Analysis) aşamasında', 'Sözdizimi Analizi (Syntax Analysis) aşamasında', 'Bağlayıcı ve Yükleyici (Linker / Loader) aşamasında'], 'Gramer açısından \'TİP TANIMLAYICI = İFADE ;\' yapısı kusursuzdur; dizge ile sayının toplanıp \'int\' değişkenine atanamayacağı bilgisi tip sistemiyle Anlamsal Analizde denetlenir.'),
  ('Derleyicide \'Sembol Tablosu\' (Symbol Table) veri yapısının temel görevi nedir ve hangi veri yapısıyla en verimli gerçeklenir?', 'Tanımlayıcıların ad, tip, kapsam (scope) ve bellek ofseti bilgilerini saklamak; hızlı arama için kapsam bağlantılı özet (hash) tablolarıyla gerçeklenir', ['Yalnızca düzenli ifadelerin DFA geçiş durumlarını saklamak; sabit boyutlu bit dizisiyle gerçeklenir', 'Çalışma zamanındaki fonksiyon çağrı adreslerini tutmak; FIFO dairesel kuyrukla gerçeklenir', 'Hedef işlemcinin tüm makine dili komutlarının ikili karşılıklarını sıralamak; yığınla gerçeklenir'], 'Sembol tablosu derleme boyunca her değişken, fonksiyon ve sınıfın özniteliklerini tutar; iç içe blok kapsamları için birbirine işaret eden hash tabloları (scoped hash tables) kullanılır.'),
  ('Somut Sözdizimi Ağacı (Parse Tree / Türetim Ağacı) ile Soyut Sözdizimi Ağacı (AST - Abstract Syntax Tree) arasındaki temel fark nedir?', 'Parse Tree gramerdeki tüm ara değişkenleri, parantezleri ve noktalı virgülleri barındırırken AST bunları eleyip yalnızca işlemsel anlam taşıyan öz yapıyı tutar', ['AST yalnızca sözcüksel analizden önce kurulurken Parse Tree makine kodu üretiminden sonra kurulur', 'Parse Tree ikili ağaç olmak zorundayken AST yalnızca doğrusal bağlı liste biçiminde tutulur', 'AST tüm değişken tiplerini silerken Parse Tree yazmaç atamalarını doğrudan içerir'], 'Örneğin \'(3 + 4)\' ifadesinde parantezler önceliği belirledikten sonra görevini tamamlamıştır; AST\'de parantez düğümü tutulmaz, doğrudan \'+\' kökünün altına \'3\' ve \'4\' bağlanır.'),
  ('Bağlamdan bağımsız bir gramerde \'E -> E + E | E * E | id\' kuralının \'belirsiz (ambiguous)\' olarak nitelendirilmesinin nedeni nedir?', '\'id + id * id\' gibi tek bir girdi dizgesi için işlem önceliğini farklı yorumlayan birden fazla farklı ayrıştırma ağacı (parse tree) üretilebilmesi', ['Gramerde iki farklı aritmetik operatörün aynı satırda dikey çizgiyle tanımlanmış olması', '\'id\' terminal sembolünün büyük harfle değil küçük harfle yazılmış olması', 'Üretim kuralının sonlu uzunlukta hiçbir dizge türetemeyip sonsuz döngüde kalması'], 'Bir gramerde en az bir dizgenin iki farklı sol-türetimi (dolayısıyla iki farklı sözdizimi ağacı: \'(id+id)*id\' ağacı ve \'id+(id*id)\' ağacı) varsa o gramer belirsizdir.'),
  ('Klasik programlama dillerindeki \'Sallanan Else (Dangling Else)\' belirsizliği (\'if (k1) if (k2) s1; else s2;\' kodunda else bloğunun hangi if\'e ait olduğu) standart derleyici gramerlerinde nasıl çözülür?', '\'else\' anahtar kelimesi kendisinden önce gelen en yakın eşleşmemiş \'if\' deyimine bağlanır', ['\'else\' her zaman en dıştaki birinci \'if\' deyimine bağlanarak içteki koşul atlanır', 'Derleyici süslü parantez olmayan her iç içe \'if\' deyimini sözdizimi hatası sayarak reddeder', 'Girinti (indentation) boşluk sayısı sayılarak C ve Java\'da bile boşluğa göre karar verilir'], 'C, C++, Java gibi süslü parantezli dillerde girinti önemsizdir; \'else\' belirsizliği her zaman en içteki (en yakın açık) \'if\' ile eşleştirilerek çözülür.'),
  ('Bir döngünün içinde her iterasyonda değeri hiç değişmeyen bir hesaplamanın (örneğin \'for (i=0; i<n; i++) dizi[i] = i + Math.sqrt(k);\' içindeki sabit \'k\' kökünün) döngünün hemen dışına, öncesine taşınması hangi derleyici eniyilemesidir?', 'Döngüden bağımsız kod taşıma (Loop-Invariant Code Motion)', ['Ölü kod eleme (Dead Code Elimination)', 'Kuyruk çağrısı birleştirme (Tail Merging)', 'Satır içi genişletme (Function Inlining)'], 'Döngü değişkenlerine bağlı olmayan ve yan etkisi bulunmayan hesaplamaları döngü dışına çıkarmak gereksiz n kez tekrar hesaplamayı 1 keze indirir.'),
  ('Derleyicinin \'x * 8\' tam sayı çarpma işlemini işlemcide çok daha hızlı çalışan \'x << 3\' (3 bit sola kaydırma) komutuna dönüştürmesi hangi eniyileme tekniğidir?', 'İşlem gücü azaltma (Strength Reduction)', ['Ortak alt ifade eleme (Common Subexpression Elimination)', 'Sözdizimsel şekerleme (Syntactic Sugaring)', 'Çöp toplama (Garbage Collection)'], 'Pahalı bir aritmetik işlemin (üs alma, çarpma, bölme) matematiksel olarak eşdeğer ama donanımda daha ucuz bir işlemle (çarpma, toplama, bit kaydırma) değiştirilmesine Strength Reduction denir.'),
  ('Küçük bir fonksiyonun çağrıldığı noktalarda CALL/RET (çağrı ve dönüş) yükünden kurtulmak için fonksiyon gövdesinin çağrı noktasına doğrudan kopyalanması (\'Function Inlining\') aşırı uygulandığında hangi olumsuz yan etkiyi doğurabilir?', 'Üretilen makine kodunun boyutunu şişirerek (code bloat) işlemcinin komut önbelleği (I-cache) isabet oranını düşürmesi', ['Fonksiyonun yerel değişkenlerinin tümünü küresel değişken haline getirerek isim çakışması yaratması', 'Özyinelemeli olmayan döngülerin çalışma zamanında yığın taşması üretmesine neden olması', 'Tam sayı aritmetiğinde yuvarlama hatalarının birikerek yanlış sonuç döndürmesi'], 'Inlining çağrı yükünü sıfırlar ve çevre kodla birlikte ek eniyileme fırsatı açar; ancak büyük fonksiyonlar çok yerde kopyalanırsa ikili kod büyür ve komut önbelleği yavaşlar.'),
  ('Java, C# veya V8 JavaScript motorlarında kullanılan Tam Zamanında Derleme (JIT - Just-In-Time Compilation) yaklaşımı yorumlama ile klasik derlemenin avantajlarını nasıl birleştirir?', 'Program çalışırken sık yürütülen sıcak bölgeleri (hot spots) tespit edip çalışma anında hedef işlemcinin doğal makine koduna derleyerek hızlandırır', ['Kaynak kodu kullanıcı klavyede her harfe bastığı anda arka planda diske \'.exe\' olarak kaydeder', 'Tüm bellek güvenliği ve dizi sınırı kontrollerini devre dışı bırakarak donanımı doğrudan yönetir', 'Yalnızca yorumlayıcı kullanarak makine kodu üretmeden bayt kodunu sıkıştırır'], 'JIT derleyici hem taşınabilir bayt koduyla hızlı başlangıç sağlar hem de çalışma zamanı profilleme verisini kullanarak en çok çalışan döngüleri yerel makine koduna çevirir.'),
  ('h(n) fonksiyonu n <= 1 ise n, n > 1 ise h(n - 1) + h(n - 2) döndürmektedir. Buna göre h(6) çağrısının sonucu kaçtır?', '8', ['5', '13', '11'], 'h(0)=0, h(1)=1, h(2)=1, h(3)=2, h(4)=3, h(5)=5 ve h(6)=5+3=8 elde edilir.'),
  ('k(n) fonksiyonu n <= 1 için 1 döndürüyor, n > 1 için k(n - 1) + k(n - 2) hesaplıyor. Önbellekleme kullanılmadığında k(4) hesaplanırken k fonksiyonu ilk çağrı dahil toplam kaç kez çağrılır?', '9', ['5', '7', '15'], 'Çağrı sayısı C(n)=1+C(n-1)+C(n-2) bağıntısıyla C(0)=1, C(1)=1, C(2)=3, C(3)=5 ve C(4)=1+5+3=9 olur.'),
  ('Bir özyinelemeli fonksiyonda özyinelemeli çağrının fonksiyonun yaptığı en son işlem olması ve dönüş değerine ek bir işlem uygulanmaması özelliğine ne ad verilir?', 'Kuyruk özyinelemesi', ['Karşılıklı özyineleme', 'Doğrusal geri izleme', 'Dinamik çizelgeleme'], 'Kuyruk özyinelemesinde (tail recursion) alt çağrıdan dönüldükten sonra bekleyen hiçbir işlem kalmaz.'),
  ('p(0) = 2 ve n > 0 için p(n) = 2 * p(n - 1) - 1 olarak tanımlanan fonksiyon için p(3) çağrısının sonucu kaçtır?', '9', ['5', '7', '17'], 'Adım adım izlendiğinde p(0)=2, p(1)=2*2-1=3, p(2)=2*3-1=5 ve p(3)=2*5-1=9 bulunur.'),
  ('Pozitif tam sayılarda üs alan us(a, b) fonksiyonu b = 0 ise 1, b çift ise us(a * a, b / 2), b tek ise a * us(a, b - 1) döndürüyor. us(2, 10) çağrısında ilk çağrı dahil toplam kaç kez us çağrısı yapılır?', '6', ['11', '4', '9'], 'Çağrı zinciri us(2,10) -> us(4,5) -> us(4,4) -> us(16,2) -> us(256,1) -> us(256,0) şeklinde toplam 6 çağrıdan oluşur.'),
  ('Çift ve tek kontrolü yapan iki fonksiyondan ciftMi(0) = Doğru, tekMi(0) = Yanlış; n > 0 için ciftMi(n) = tekMi(n - 1) ve tekMi(n) = ciftMi(n - 1) tanımlıdır. ciftMi(3) çağrısının sonucu ve toplam fonksiyon çağrısı sayısı nedir?', 'Yanlış, 4 çağrı', ['Doğru, 3 çağrı', 'Yanlış, 3 çağrı', 'Doğru, 4 çağrı'], 'ciftMi(3) -> tekMi(2) -> ciftMi(1) -> tekMi(0) = Yanlış zinciriyle toplam 4 çağrı yapılır ve Yanlış döner.'),
  ('Tam sayı bölmesiyle tanımlanan s(n) fonksiyonu n < 10 ise n, n >= 10 ise (n mod 10) + s(n div 10) döndürmektedir. s(4729) çağrısının sonucu kaçtır?', '22', ['18', '26', '4'], 'Fonksiyon sayının basamakları toplamını hesaplar: 9 + 2 + 7 + 4 = 22.'),
  ('yaz(n) prosedürü n <= 0 ise hiçbir şey yapmıyor; n > 0 ise önce ekrana n yazdırıp sonra yaz(n - 1) çağırıyor ve dönüşte tekrar n yazdırıyor. yaz(3) çağrısının ekran çıktısı nedir?', '3 2 1 1 2 3', ['1 2 3 3 2 1', '3 2 1 0 1 2 3', '1 1 2 2 3 3'], 'İniş aşamasında 3, 2, 1 yazdırılır; yaz(0) taban durumundan dönerken yığından sırasıyla 1, 2, 3 yazdırılır.'),
  ('izle(n) prosedürü n > 0 iken önce izle(n div 2) çağırıyor, ardından ekrana (n mod 2) değerini yazdırıyor (n = 0 ise duruyor). izle(13) çağrısının ekran çıktısı nedir?', '1101', ['1011', '1110', '1001'], 'Yığın dönüşünde kalanlar en anlamlı bitten başlayarak yazdırıldığı için 13 sayısının ikili tabandaki karşılığı olan 1101 üretilir.'),
  ('Hanoi Kuleleri probleminde 4 diski kurallara uygun biçimde kaynak çubuktan hedef çubuğa taşımak için gereken en az hamle sayısı kaçtır?', '15', ['8', '16', '31'], 'n disk için minimum hamle sayısı H(n) = 2 * H(n - 1) + 1 = 2^n - 1 bağıntısıyla 2^4 - 1 = 15 olur.'),
  ('Öklid algoritmasını özyinelemeli uygulayan ebob(a, b) fonksiyonu b = 0 ise a, b > 0 ise ebob(b, a mod b) döndürmektedir. ebob(48, 18) hesaplanırken ilk çağrı dahil kaç kez ebob çağrılır?', '4', ['2', '3', '6'], 'Çağrılar sırasıyla ebob(48, 18) -> ebob(18, 12) -> ebob(12, 6) -> ebob(6, 0) = 6 olup toplam 4 çağrı gerçekleşir.'),
  ('Bir dizide özyinelemeli ikili arama yapan fonksiyon her adımda arama aralığını yarıya indirmektedir. 64 elemanlı sıralı bir dizide aranan eleman dizide yoksa en kötü durumda boş olmayan alt diziler için en fazla kaç karşılaştırma çağrısı yapılır?', '7', ['5', '9', '32'], 'Uzunluklar 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1 şeklinde yarıya inerek toplam 7 karşılaştırma adımında sonlanır.'),
  ('Aynı alt problemleri tekrar tekrar çözen özyinelemeli bir fonksiyonda, hesaplanan sonuçların bir tabloda saklanarak yeniden gerektiğinde doğrudan tablodan döndürülmesi tekniğine ne ad verilir?', 'Üstten aşağı önbellekleme (memoization)', ['Alttan yukarı döngü açma (loop unrolling)', 'Statik tekil atama (SSA dönüşümü)', 'Sabit katlama (constant folding)'], 'Memoization tekniği özyinelemeli yapıyı koruyarak daha önce hesaplanmış alt problem sonuçlarını önbellekten döndürür.'),
  ('ters(s) fonksiyonu metin uzunluğu <= 1 ise s döndürüyor, aksi halde ters(s[1..son]) + s[0] işlemini yapıyor. "KALE" girdisi için taban durumuna ulaşılana kadar oluşturulan alt çağrı argümanları sırasıyla hangileridir?', '"ALE", "LE", "E"', ['"KAL", "KA", "K"', '"ELA", "EL", "E"', '"LE", "E", "K"'], 'İlk karakter her adımda sona eklenmek üzere ayrıldığından alt çağrılara sırasıyla "ALE", "LE" ve taban durumu olan "E" gönderilir.'),
  ('Pascal üçgenindeki binom katsayısını C(n, k) = (k == 0 veya k == n ise 1, değilse C(n - 1, k - 1) + C(n - 1, k)) ile hesaplayan fonksiyon için C(5, 2) değeri kaçtır?', '10', ['5', '15', '20'], 'C(5,2) = C(4,1) + C(4,2) = 4 + 6 = 10 sonucunu döndürür.'),
  ('Kuyruk özyinelemeli faktöriyel fonksiyonu fak(n, birikim): n == 0 ise birikim, n > 0 ise fak(n - 1, n * birikim) biçiminde tanımlıdır. fak(4, 1) çağrısında gerçekleşen üçüncü çağrının parametreleri nedir?', 'fak(2, 12)', ['fak(2, 6)', 'fak(3, 4)', 'fak(1, 24)'], '1. çağrı fak(4,1), 2. çağrı fak(3,4), 3. çağrı fak(2,12), 4. çağrı fak(1,24), 5. çağrı fak(0,24) olur.'),
  ('Dizi toplamını böl ve yönet yaklaşımıyla hesaplayan top(A, sol, sag) fonksiyonu sol == sag ise A[sol], değilse orta = (sol + sag) div 2 için top(A, sol, orta) + top(A, orta + 1, sag) döndürüyor. 5 elemanlı bir dizi için ilk çağrı dahil toplam kaç kez top çağrılır?', '9', ['5', '7', '15'], 'N yapraklı tam ikili çağrı ağacında her iç düğüm iki çocuk açtığından toplam düğüm (çağrı) sayısı 2N - 1 = 2(5) - 1 = 9 olur.'),
  ('Özyinelemeli geri izleme (backtracking) algoritmalarında bir dalın çözüme ulaşamayacağı anlaşıldığında dalın terk edilip önceki karar noktasına dönülmesi işlemine ne ad verilir?', 'Budama (pruning)', ['Düzleştirme (flattening)', 'Sıraya koyma (serialization)', 'Öngetirme (prefetching)'], 'Çözüm uzayında geçersiz alt ağaçların erken kesilerek geri dönülmesine budama (pruning) denir.'),
  ('"5 3 + 8 2 - *" postfix (RPN) ifadesi bir yığın yardımıyla değerlendirildiğinde elde edilen sayısal sonuç kaçtır?', '48', ['14', '46', '60'], '(5 + 3) = 8 ve (8 - 2) = 6 hesaplanıp çarpıldığında 8 * 6 = 48 bulunur.'),
  ('"20 4 / 3 + 2 *" postfix (RPN) ifadesinin değerlendirilmesi sonucunda hangi değer elde edilir?', '16', ['11', '4', '22'], 'Adımlar sırasıyla: 20 / 4 = 5, 5 + 3 = 8 ve 8 * 2 = 16 şeklindedir.'),
  ('Soldan sağa yığınla postfix değerlendirme yapılırken "-" veya "/" gibi değişme özelliği olmayan ikili bir işleçle karşılaşıldığında yığından ilk çekilen (pop edilen) eleman işlemin neresine yerleştirilir?', 'Sağ işlenen (ikinci operand) konumuna', ['Sol işlenen (ilk operand) konumuna', 'Yığının en altındaki taban konumuna', 'Bir sonraki işlecin öncelik konumuna'], 'Yığına önce sol işlenen, sonra sağ işlenen itildiği için LIFO gereği ilk çekilen değer sağ işlenendir (ikinciÇekilen op ilkÇekilen).'),
  ('Bir prefix ifadeyi tek bir yığın kullanarak tek geçişte değerlendirmek isteyen bir algoritma ifadeyi hangi yönde taramalıdır?', 'Sağdan sola doğru', ['Soldan sağa doğru', 'Ortadan iki uca doğru', 'Önce işleçleri sonra sayıları'], 'Prefix gösterimde işleçler işlenenlerin solunda bulunduğundan, işlenenleri önce yığına atabilmek için ifade sağdan sola taranır.'),
  ('"- * + 2 3 4 6" prefix ifadesinin değerlendirilmesi sonucunda hangi sayı elde edilir?', '14', ['8', '12', '26'], '(+ 2 3) = 5, (* 5 4) = 20 ve (- 20 6) = 14 olarak hesaplanır.'),
  ('Edsger Dijkstra tarafından geliştirilen ve infix ifadeleri işleç öncelikleri ile birleşme yönlerini gözeterek yığın yardımıyla postfix gösterime dönüştüren klasik algoritmanın adı nedir?', 'Manevra İstasyonu (Shunting-yard) algoritması', ['Knuth-Morris-Pratt eşleştirme algoritması', 'Cocke-Younger-Kasami ayrıştırma algoritması', 'Bellman-Ford en kısa yol algoritması'], 'Tren vagonlarının makaslarla yönlendirilmesine benzetilen Dijkstra\'nın infix-postfix dönüşüm algoritması Shunting-yard algoritmasıdır.'),
  ('"(A + B) * (C - D)" infix ifadesinin prefix (Lehçe) gösterimindeki karşılığı aşağıdakilerden hangisidir?', '* + A B - C D', ['+ A B * - C D', '* - C D + A B', 'A B + C D - *'], 'Ana işleç çarpmadır; sol alt ifade (+ A B), sağ alt ifade (- C D) olduğundan prefix gösterim "* + A B - C D" olur.'),
  ('Shunting-yard algoritmasıyla infix bir ifade postfix\'e çevrilirken girdide kapanış parantezi ")" görüldüğünde işleç yığınında ne yapılır?', 'Açılış parantezi "(" görülene kadar işleçler yığından çekilip çıktıya eklenir ve "(" atılır', ['Yığındaki tüm işleçler koşulsuz biçimde çıktıya aktarılıp yığın tamamen sıfırlanır', 'Kapanış parantezi doğrudan işleç yığınına itilerek bir sonraki işlenen beklenir', 'Yalnızca en üstteki tek bir işleç çekilip çıktıya yazılır ve parantezler çıktıya kopyalanır'], 'Kapanış parantezi o alt ifadenin bittiğini gösterir; eşleşen "(" bulunana dek aradaki tüm işleçler çıktıya aktarılır ve parantezler çıktıya yazılmaz.'),
  ('Bir aritmetik ifade ağacı üzerinde son-kök (post-order: sol, sağ, kök) gezinmesi yapıldığında düğümlerin ziyaret sırası hangi gösterimi doğrudan üretir?', 'Postfix (Ters Lehçe) gösterimini', ['Prefix (Lehçe) gösterimini', 'Tam parantezsiz infix gösterimini', 'Seviye sıralı kuyruk gösterimini'], 'Post-order gezinmede önce sol ve sağ işlenen alt ağaçları, en son kök işleç yazıldığından doğrudan postfix ifade elde edilir.'),
  ('Bir aritmetik ifade ağacı üzerinde ön-kök (pre-order: kök, sol, sağ) gezinmesi yapıldığında elde edilen dizilim hangi gösterime karşılık gelir?', 'Prefix (Lehçe) gösterimine', ['Postfix (Ters Lehçe) gösterimine', 'Standart infix gösterimine', 'Ters seviye öncelikli gösterime'], 'Pre-order gezinmede önce kök işleç, ardından sol ve sağ alt ifadeler ziyaret edildiğinden doğrudan prefix gösterim üretilir.'),
  ('"8 3 - 2 ^ 4 +" postfix ifadesinde "^" üs alma işlemini gösterdiğine göre ifadenin sayısal sonucu kaçtır?', '29', ['14', '20', '81'], '8 - 3 = 5; 5 ^ 2 = 25 ve 25 + 4 = 29 olarak hesaplanır.'),
  ('Shunting-yard algoritmasında girdiden okunan sol-birleşmeli "+" işleci işlenirken işleç yığınının en üstünde "*" işleci bulunuyorsa nasıl bir adım izlenir?', '"*" daha yüksek öncelikli olduğundan yığından çekilip çıktıya yazılır, ardından "+" yığın koşulları sağlanınca yığına itilir', ['"+" doğrudan "*" işlecinin üzerine itilerek çarpma işleminin sonraya kalması sağlanır', 'Her iki işleç de yığından silinerek sözdizimi uyuşmazlığı hatası bildirilir', 'Çıktı kuyruğundaki son iki sayı geri alınıp yeniden girdi akışının başına eklenir'], 'Yığının tepesindeki işleç daha yüksek veya (sol-birleşmelilerde) eşit öncelikliyse önce o değerlendirilmelidir; bu yüzden çıktıya aktarılır.'),
  ('"* - 7 2 + 4 1" prefix ifadesinin eşdeğer postfix (RPN) gösterimi aşağıdakilerden hangisidir?', '7 2 - 4 1 + *', ['7 2 4 1 + - *', '7 2 - * 4 1 +', '4 1 + 7 2 - /'], 'İfade (7 - 2) * (4 + 1) yapısındadır; bunun postfix karşılığı "7 2 - 4 1 + *" biçimindedir.'),
  ('"4 5 * 6 2 / - 7 +" postfix ifadesinin sayısal sonucu kaçtır?', '24', ['10', '17', '30'], '4 * 5 = 20 ve 6 / 2 = 3 hesaplanır; 20 - 3 = 17 ve 17 + 7 = 24 elde edilir.'),
  ('Bir özyinelemeli fonksiyon her çağrıda n değerini 3 azaltarak t(n - 3) çağrısı yapmakta ve n == 0 olduğunda durmaktadır. Bu fonksiyona pozitif bir tam sayı olan n = 14 verildiğinde ne olur?', 'Taban durumu olan 0 atlandığı için negatif sayılara inerek sonsuz özyinelemeye (yığın taşmasına) girer', ['Tam 4 çağrı sonunda n değeri kendiliğinden 0 değerine yuvarlanarak güvenli biçimde durur', 'Derleyici derleme aşamasında 14 sayısının 3 ile bölünemediğini saptayıp sözdizimi hatası verir', 'Fonksiyon taban durumuna en yakın değer olan 2 sayısında otomatik olarak durup 2 döndürür'], '14 -> 11 -> 8 -> 5 -> 2 -> -1 -> -4 ... şeklinde ilerlediği için n == 0 koşulu hiçbir zaman sağlanmaz (n <= 0 yazılmalıydı).'),
  ('Başlangıç simgesi S olan bir gramerde S -> aSb | ab üretim kuralları verilmiştir. Bu gramerin ürettiği dil aşağıdakilerden hangisidir?', 'n >= 1 olmak üzere a^n b^n dizgileri kümesi', ['n >= 0 olmak üzere eşit sayıda karışık a ve b içeren tüm dizgiler', 'Herhangi bir sayıda a ardından herhangi bir sayıda b gelen dizgiler', 'Yalnızca çift uzunluklu tüm a ve b kombinasyonlarından oluşan dizgiler'], 'Her adımda sola bir \'a\' ve sağa bir \'b\' eklendiğinden ve tabanda \'ab\' bulunduğundan dil {a^n b^n | n >= 1} olur.'),
  ('Başlangıç simgesi S olan S -> aSa | bSb | c grameri aşağıdaki dizgilerden hangisini türetebilir?', 'abacaba', ['abccba', 'abacab', 'aabbaa'], 'Gramer tam ortasında tek bir \'c\' bulunan palindromları (w c w^R) üretir: S -> aSa -> abSba -> abaSaba -> abacaba.'),
  ('Bir bağlamdan bağımsız gramerde en az bir dizgi için iki veya daha fazla farklı ayrıştırma ağacı (parse tree) üretilebiliyorsa bu gramer nasıl nitelendirilir?', 'Belirsiz (ambiguous) gramer', ['Sol-özyinelemeli (left-recursive) gramer', 'Deterministik (LL) gramer', 'Chomsky normal formundaki gramer'], 'Aynı dizginin birden fazla ayrıştırma ağacına sahip olması anlamsal yorum farkı doğurur ve böyle gramerlere belirsiz (ambiguous) gramer denir.'),
  ('Programlama dillerinde if C1 then if C2 then S1 else S2 yapısında else dalının hangi if ile eşleşeceğinin gramerde tekil olmaması durumuna ne ad verilir?', 'Sallanan else (dangling else) belirsizliği', ['Sol çarpanlara ayırma (left factoring) hatası', 'Kuyruk çağrısı yığın taşması', 'Tür çıkarımı döngüsel bağımlılığı'], 'İçteki ve dıştaki if deyimlerinden hangisinin else bloğunu alacağının belirsiz kalması klasik "dangling else" problemidir.'),
  ('Her türetme adımında daima en soldaki uçbirim olmayan (non-terminal) simgenin bir üretim kuralıyla açılmasına ne ad verilir?', 'En soldan türetme (leftmost derivation)', ['En sağdan indirgeme (rightmost reduction)', 'Alttan yukarı kaydırma (shift-reduce)', 'Sözcüksel belirteçleştirme (tokenization)'], 'Soldan ilk değişkenin her adımda yeniden yazıldığı türetme biçimi en soldan türetmedir (leftmost derivation).'),
  ('S -> AB, A -> aA | a, B -> bB | ε kurallarıyla tanımlanan gramer aşağıdaki dizgilerden hangisini ÜRETEMEZ?', 'bbba', ['a', 'aaab', 'abbb'], 'A değişkeni en az bir adet \'a\' üretmek zorundadır (A -> a); dolayısıyla hiç \'a\' içermeyen veya \'b\' ile başlayan bbba dizgisi üretilemez.'),
  ('Üstten aşağı ayrıştırmaya hazırlık için A -> αβ1 | αβ2 biçimindeki ortak ön ekli kuralların A -> αA\' ve A\' -> β1 | β2 şekline dönüştürülmesi işlemine ne ad verilir?', 'Sol çarpanlara ayırma (left factoring)', ['Sol özyinelemeyi kaldırma (left-recursion elimination)', 'Sabit yayılımı (constant propagation)', 'Ölü kod elemesi (dead code elimination)'], 'Ayrıştırıcının tek ileri bakışla hangi kuralı seçeceğini bilebilmesi için ortak ön ekin ayrılmasına sol çarpanlara ayırma denir.'),
  ('Sözcüksel çözümleyicilerde >= veya ++ gibi çok karakterli işleçleri okurken tek karakterde durmayıp mümkün olan en uzun geçerli belirteci eşleştirme ilkesine ne ad verilir?', 'En uzun eşleşme (maximal munch) kuralı', ['Tembel değerlendirme (lazy evaluation) kuralı', 'Kısa devre (short-circuit) mantık kuralı', 'Açgözlü yazmaç boyama (graph coloring) kuralı'], 'Maximal munch ilkesi uyarınca lexer örneğin == gördüğünde iki ayrı = yerine tek bir eşitlik karşılaştırma belirteci üretir.'),
  ('x = (a + b) * c; deyimi için oluşturulan bir Soyut Sözdizimi Ağacında (AST) en üstteki kök düğüm ve onun sağ çocuğu sırasıyla neyi temsil eder?', 'Kök düğüm = atama işlemini, sağ çocuğu * çarpma işlemini', ['Kök düğüm ; sonlandırıcısını, sağ çocuğu c değişkenini', 'Kök düğüm + toplama işlemini, sağ çocuğu = atama işlemini', 'Kök düğüm ( parantezini, sağ çocuğu ) parantezini'], 'Atama deyiminde kök = düğümüdür; sol çocuğu hedef değişken x, sağ çocuğu ise hesaplanan ifadenin ana işleci olan * düğümüdür.'),
  ('Her uçbirim olmayan gramer simgesi için ayrı bir fonksiyon yazarak girdiyi soldan sağa doğru üstten aşağı ayrıştıran yaygın el yapımı ayrıştırıcı tekniğine ne ad verilir?', 'Özyinelemeli iniş ayrıştırıcısı', ['LR(1) tablo güdümlü alttan yukarı ayrıştırıcı', 'Operatör öncelikli yığın birleştiricisi', 'Dinamik CYK matris ayrıştırıcısı'], 'Gramer kurallarını birbirini çağıran fonksiyonlar olarak kodlayan üstten aşağı ayrıştırıcıya özyinelemeli iniş ayrıştırıcısı denir.'),
  ('Değişken tiplerinin ve tür uyumunun program çalıştırılmadan önce, derleme zamanında (compile-time) doğrulandığı tip sistemlerine ne ad verilir?', 'Statik tip sistemi (static typing)', ['Dinamik tip sistemi (dynamic typing)', 'Zayıf örtük tip sistemi (duck typing)', 'Yorumlamalı çalışma zamanı etiketlemesi'], 'C, Java, Rust ve Haskell gibi dillerde tür kuralları derleme zamanında statik tip denetimiyle doğrulanır.'),
  ('Programcının açıkça tip yazmasına gerek kalmadan derleyicinin ifadelerden ve kullanımlardan değişken ve fonksiyon tiplerini otomatik olarak hesaplaması özelliğine ne ad verilir?', 'Tip çıkarımı (type inference)', ['Tür zorlaması (type coercion)', 'Tür silinmesi (type erasure)', 'Yeniden yorumlamalı dönüştürme (reinterpret cast)'], 'Hindley-Milner gibi algoritmalarla tiplerin açık bildirim olmadan derleme zamanında türetilmesine tip çıkarımı denir.'),
  ('3 + 4.5 ifadesini değerlendirirken derleyicinin 3 tam sayısını veri kaybı olmaması için otomatik olarak 3.0 kayan noktalı sayısına dönüştürmesine ne ad verilir?', 'Örtük tür dönüşümü / genişletme (implicit type coercion / widening)', ['Açık daraltıcı tür kesmesi (explicit narrowing truncation)', 'Sözdizimsel şekerleme (syntactic desugaring)', 'İşaretçi takma ad analizi (pointer alias analysis)'], 'Farklı sayısal tipler arasındaki işlemlerde derleyicinin dar tipi geniş tipe kendiliğinden yükseltmesine örtük tür dönüşümü (coercion) denir.'),
  ('Derleyicinin ön ucu (front-end) ile arka ucu (back-end) arasında köprü görevi gören, kaynak dilden ve hedef işlemciden bağımsız kod temsiline ne ad verilir?', 'Ara temsil / Ara kod', ['İkili yürütülebilir ELF başlığı', 'Sözcüksel düzenli ifade tablosu', 'Donanım mikro-kod dizilimi'], 'Üç adresli kod veya LLVM IR gibi ara temsiller, M kaynak dili N hedef mimariye M*N yerine M+N bileşenle bağlamayı sağlar.'),
  ('a = 5; b = a + 3; kod parçasında a\'nın sabit olduğunun izlenerek ikinci satırda a yerine doğrudan 5 yerleştirilmesi işlemine ne ad verilir?', 'Sabit yayılımı (constant propagation)', ['Kuyruk çağrısı elemesi (tail-call elimination)', 'Kuvvet azaltma (strength reduction)', 'Yazmaç dökülmesi (register spilling)'], 'Sabit değer atanmış değişkenlerin kullanıldığı yerlere o sabit değerin taşınması sabit yayılımıdır (ardından sabit katlama ile 8 bulunur).'),
  ('Bir fonksiyonda return sonuc; satırından hemen sonra yazılmış olan ve hiçbir kontrol akışı yolundan ulaşılamayan deyimlerin derleyici tarafından koddan çıkarılmasına ne ad verilir?', 'Ölü / ulaşılamaz kod elemesi (dead / unreachable code elimination)', ['Döngü değişmezi taşıma (loop-invariant code motion)', 'Dal tahmini spekülasyonu (branch prediction)', 'Dinamik profilleme (dynamic profiling)'], 'Programın çıktısını etkilemeyen veya hiçbir zaman çalışmayacak olan kod bloklarının silinmesine ölü/ulaşılamaz kod elemesi denir.'),
  ('x = (a + b) * c; y = (a + b) + d; kodunda a + b işleminin iki kez hesaplanması yerine t = a + b; x = t * c; y = t + d; şekline dönüştürülmesi hangi eniyileştirmedir?', 'Ortak alt ifade elemesi (Common Subexpression Elimination - CSE)', ['Döngü birleştirme (loop fusion)', 'Sanal metot tablosu bağlama (vtable dispatch)', 'Çöp toplama sıkıştırması (compaction)'], 'Değişkenleri değişmediği halde tekrarlanan özdeş hesaplamaların geçici değişkende tutulup yeniden kullanılmasına ortak alt ifade elemesi denir.'),
  ('Bir döngünün içinde yer alan ancak değeri döngü sayacına veya döngüde değişen hiçbir değişkene bağlı olmayan k = m * n; hesabının döngünün dışına (önüne) alınmasına ne ad verilir?', 'Döngü değişmezi kod taşıma (loop-invariant code motion)', ['Döngü ters çevirme (loop reversal)', 'Yığın çerçevesi hizalama (stack alignment)', 'İşaretçi sıkıştırma (pointer compression)'], 'Her yinelemede aynı sonucu üreten hesaplamaların döngü öncesine çekilerek bir kez yapılması döngü değişmezi kod taşımadır.'),
  ('Hedef işlemcide pahalı olan x * 8 tam sayı çarpma işleminin derleyici tarafından daha hızlı çalışan x << 3 (sola bit kaydırma) işlemine dönüştürülmesi hangi eniyileştirme tekniğine örnektir?', 'Kuvvet azaltma (strength reduction)', ['Sabit katlama (constant folding)', 'Satır içi genişletme (inlining)', 'Kaçış analizi (escape analysis)'], 'Maliyetli bir işlemin matematiksel olarak eşdeğer ama donanımda daha ucuz olan bir işlemle değiştirilmesine kuvvet azaltma denir.'),
  ('Küçük ve sık çağrılan bir fonksiyonun çağrı noktasında CALL komutu üretmek yerine fonksiyon gövdesinin doğrudan çağrıldığı yere kopyalanması eniyileştirmesine ne ad verilir?', 'Fonksiyon satır içi açma (function inlining)', ['Sanal tablo yönlendirmesi (dynamic dispatch)', 'Tembel bağlama (lazy binding)', 'Gecikmeli dallanma (delayed branching)'], 'Function inlining, çağrı/dönüş ek yükünü ortadan kaldırır ve çevreleyen kodla birlikte ek eniyileştirme fırsatları açar.'),
  ('JIT derleyicili modern sanal makinelerde (örneğin Java HotSpot veya V8) program ilk başladığında tüm kodu hemen ağır eniyileştirmelerle derlemek yerine genellikle nasıl bir strateji izlenir?', 'Kod önce yorumlayıcı veya hızlı temel derleyiciyle çalıştırılır, profilleyiciyle "sıcak noktalar" (hot spots) belirlendikçe ağır JIT eniyileştirmesi uygulanır', ['Program başlamadan önce tüm kütüphaneler saatlerce süren tam derlemeden geçirilir ve çalışma anında hiç izleme yapılmaz', 'Yalnızca hiç çağrılmayan soğuk fonksiyonlar makine koduna çevrilir, döngüler ise daima yorumlayıcıda bırakılır', 'Her fonksiyon çağrısında üretilen makine kodu silinerek aynı fonksiyon her seferinde baştan ayrıştırılır'], 'Katmanlı derleme (tiered compilation) yaklaşımı hızlı başlangıç süresi ile yüksek tepe başarımını dengeler.'),
  ('Python (CPython) veya Java gibi dillerde kaynak kodun doğrudan donanım makine koduna değil de sanal makinenin anlayacağı taşınabilir ara biçime çevrilmesiyle üretilen koda ne ad verilir?', 'Bayt kodu (bytecode)', ['Mikro-işlem kodu (microcode)', 'Çevirici sembolik kodu (assembly)', 'Önişlemci makro metni'], 'Sanal makine tarafından yorumlanan veya JIT ile derlenen kompakt ara koda bayt kodu (bytecode) denir.'),
  ('Bir derleyicinin kaynak kodu hedef koda çevirirken geçtiği standart aşamaların baştan sona doğru sıralaması aşağıdakilerden hangisidir?', 'Sözcüksel çözümleme -> Sözdizimi çözümlemesi -> Anlamsal çözümleme -> Ara kod üretimi ve eniyileştirme -> Hedef kod üretimi', ['Sözdizimi çözümlemesi -> Sözcüksel çözümleme -> Hedef kod üretimi -> Anlamsal çözümleme -> Ara kod eniyileştirme', 'Anlamsal çözümleme -> Ara kod üretimi -> Sözcüksel çözümleme -> Sözdizimi çözümlemesi -> Hedef kod üretimi', 'Hedef kod üretimi -> Ara kod eniyileştirme -> Sözdizimi çözümlemesi -> Anlamsal çözümleme -> Sözcüksel çözümleme'], 'Derleyici boru hattı sırasıyla Lexer -> Parser -> Semantic Analyzer -> IR & Optimizer -> Code Generator aşamalarını izler.'),
  ('Ayrıştırıcının (parser) ilk sözdizimi hatasında durmak yerine noktalı virgül veya blok sonu gibi eşitleyici belirteçlere kadar girdiyi atlayıp kalan hataları da bulmaya devam etmesi stratejisine ne ad verilir?', 'Panik modu hata kurtarma (panic-mode error recovery)', ['Kuyruk çağrısı eniyileştirmesi (tail-call optimization)', 'Spekülatif dal tahmini (speculative branch prediction)', 'Dinamik tür zorlaması (dynamic type coercion)'], 'Panic-mode kurtarma, ayrıştırıcının güvenli bir senkronizasyon belirtecine (;, }) kadar ilerleyip tek derlemede birden çok hatayı bildirmesini sağlar.'),
  ('S -> ( S ) S | ε bağlamdan bağımsız grameri hangi dili tam olarak tanımlar?', 'Dengeli (iyi eşleşmiş) tüm parantez dizgileri dilini', ['Açılış parantezi sayısı kapanıştan daima fazla olan dizgileri', 'Yalnızca tek bir parantez çifti içerebilen sabit dizgileri', 'İç içe geçmeye izin vermeyen ardışık ()()() dizgilerini'], 'Bu klasik Dyck grameri hem iç içe ((())) hem de yan yana ()() birleşimleri kapsayan tüm dengeli parantez dizgilerini üretir.'),
  ('Programlama dillerinde a[i] veya x += 1 gibi okunabilirliği artıran ancak derleyicinin erken aşamada daha temel çekirdek yapılara (x = x + 1 gibi) dönüştürdüğü dil olanaklarına ne ad verilir?', 'Sözdizimsel şeker (syntactic sugar)', ['Bağlama duyarlı belirsizlik (context ambiguity)', 'Donanım kesme sinyali (hardware interrupt)', 'Yığın çerçevesi taşması (stack frame spill)'], 'Dilin ifade gücünü değiştirmeden yazım kolaylığı sağlayan ve AST aşamasında temel yapılara indirgenen özelliklere sözdizimsel şeker denir.'),
  ('Derleyici akış analizinde tek bir giriş noktası ve tek bir çıkış noktası bulunan, içinden dışarıya veya dışarıdan içine ara dallanma (jump/branch) içermeyen ardışık komut dizisine ne ad verilir?', 'Temel blok (basic block)', ['Sözcüksel çerçeve (lexical frame)', 'Soyut sözdizimi yaprağı (AST leaf)', 'Sanal metot tablosu (vtable)'], 'Kontrol Akış Çizgesinin (CFG - Control Flow Graph) düğümlerini oluşturan dallanmasız düz kod parçalarına temel blok denir.'),
  ('Derleyicinin ürettiği nesne dosyalarını (object files) ve dış kütüphaneleri birleştirip sembol referanslarını gerçek adreslerle eşleştirerek çalıştırılabilir dosya üreten sistem aracı hangisidir?', 'Bağlayıcı (linker)', ['Sözcüksel tarayıcı (scanner)', 'Sözdizimi ayrıştırıcısı (parser)', 'Soyut ağaç gezgini (tree walker)'], 'Ayrı derlenmiş modüllerdeki dış fonksiyon ve değişken sembollerini çözümleyip birleştiren araç bağlayıcıdır (linker).'),
  ('Bir yorumlayıcının kaynak kodu AST\'ye çevirdikten sonra bayt kodu üretmeden doğrudan AST düğümlerini özyinelemeli fonksiyonlarla gezerek çalıştırması yöntemine ne ad verilir?', 'Ağaç gezintili yorumlama (tree-walk interpretation)', ['Kayıt tabanlı JIT derleme (register JIT)', 'Statik ikili çeviri (static binary translation)', 'Vektörel döngü paralelleştirme (SIMD vectorization)'], 'AST düğümleri üzerinde özyinelemeli eval(dugum) çağrıları yaparak ifadeleri doğrudan hesaplayan basit yorumlayıcı modeline tree-walk interpreter denir.'),
  ('S -> aB | bA, A -> a | aS | bAA, B -> b | bS | aBB bağlamdan bağımsız gramerinin ürettiği boş olmayan dizgilerin temel ortak özelliği nedir?', 'İçerdikleri \'a\' harfi sayısı ile \'b\' harfi sayısının birbirine eşit olması', ['Yalnızca \'a\' ile başlayıp yalnızca \'b\' ile sonlanan dizgiler olmaları', 'Uzunluklarının her zaman 3 sayısının tam katı olması', 'Hiçbir zaman yan yana iki aynı harf (\'aa\' veya \'bb\') içermemeleri'], 'S eşit sayıda a ve b, A bir fazla a, B ise bir fazla b üretir; tümevarımla S\'den türeyen tüm dizgilerde \'a\' ve \'b\' sayıları eşittir.'),
  ('C/C++ dillerinde #include ve #define gibi yönergelerin derleyicinin sözcüksel çözümleyicisinden bile önce metinsel olarak işlendiği aşamaya ne ad verilir?', 'Önişleme (preprocessing) aşaması', ['Tam zamanında derleme (JIT) aşaması', 'Statik tekil atama (SSA) aşaması', 'Kayıt boyama (register coloring) aşaması'], 'Makro açma ve başlık dosyası ekleme işlemleri derleme öncesi metin dönüşümü yapan önişlemci (preprocessor) tarafından yürütülür.'),
  ('Derleyici eniyileştirmelerinde "kısa devre değerlendirme" (short-circuit evaluation) kodu üretildiğinde if (p != NULL && p->deger > 0) koşulunda p == NULL ise ikinci karşılaştırmaya ne olur?', 'Koşullu atlama komutuyla ikinci ifade hiç çalıştırılmadan atlanır ve geçersiz bellek erişimi (null dereference) önlenir', ['Her iki taraf da paralel hesaplanıp sonuçları mantıksal VE kapısına sokulduğu için bellek hatası oluşur', 'Derleyici p->deger ifadesini döngü değişmezi sayarak if deyiminin üstüne taşır', 'İkinci ifade derleme zamanında sabit katlama ile sıfıra eşitlenerek tamamen silinir'], 'Short-circuit kod üretiminde && işlecinin sol tarafı yanlışsa sağ tarafı değerlendiren temel bloğa hiç girilmeden yanlış dalına atlanır.'),
];
